-- ═══════════════════════════════════════════
-- 109: Batch RPC to reduce connection usage
-- ═══════════════════════════════════════════

-- Batch version of fn_calc_pp_producible_qty
-- Accepts array of product_ids, returns table of (product_id, producible_qty)
-- Reduces N concurrent RPC calls to 1 single call

CREATE OR REPLACE FUNCTION fn_calc_pp_producible_qty_batch(p_product_ids UUID[])
RETURNS TABLE(product_id UUID, producible_qty NUMERIC)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  v_pid       UUID;
  v_recipe_id UUID;
  v_min_qty   NUMERIC;
  v_inc       RECORD;
  v_on_hand   NUMERIC;
  v_possible  NUMERIC;
BEGIN
  FOREACH v_pid IN ARRAY p_product_ids
  LOOP
    v_min_qty := NULL;
    SELECT r.id INTO v_recipe_id FROM pp_recipes r WHERE r.product_id = v_pid;

    IF v_recipe_id IS NOT NULL THEN
      FOR v_inc IN
        SELECT ri.product_id AS inc_product_id, ri.qty
        FROM pp_recipe_includes ri
        WHERE ri.recipe_id = v_recipe_id AND ri.qty > 0
      LOOP
        SELECT COALESCE(sb.on_hand, 0) INTO v_on_hand
        FROM inv_stock_balances sb
        WHERE sb.product_id = v_inc.inc_product_id;

        v_on_hand := COALESCE(v_on_hand, 0);
        v_possible := FLOOR(v_on_hand / v_inc.qty);

        IF v_min_qty IS NULL OR v_possible < v_min_qty THEN
          v_min_qty := v_possible;
        END IF;
      END LOOP;
    END IF;

    product_id := v_pid;
    producible_qty := COALESCE(v_min_qty, 0);
    RETURN NEXT;
  END LOOP;
END;
$$;

-- Batch validation: check RM stock for multiple production items at once
-- Returns table of (product_id, include_product_code, needed, on_hand)
-- Only returns rows where stock is insufficient

CREATE OR REPLACE FUNCTION fn_validate_production_items_batch(
  p_items JSONB  -- array of { "product_id": uuid, "qty": numeric }
)
RETURNS TABLE(
  pp_product_id UUID,
  include_product_code TEXT,
  needed NUMERIC,
  on_hand NUMERIC
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
  v_item      JSONB;
  v_recipe_id UUID;
  v_inc       RECORD;
  v_oh        NUMERIC;
  v_need      NUMERIC;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT r.id INTO v_recipe_id
    FROM pp_recipes r
    WHERE r.product_id = (v_item->>'product_id')::UUID;

    IF v_recipe_id IS NULL THEN CONTINUE; END IF;

    FOR v_inc IN
      SELECT ri.product_id AS inc_pid, ri.qty,
             p.product_code AS inc_code
      FROM pp_recipe_includes ri
      JOIN pr_products p ON p.id = ri.product_id
      WHERE ri.recipe_id = v_recipe_id AND ri.qty > 0
    LOOP
      v_need := v_inc.qty * (v_item->>'qty')::NUMERIC;

      SELECT COALESCE(sb.on_hand, 0) INTO v_oh
      FROM inv_stock_balances sb
      WHERE sb.product_id = v_inc.inc_pid;

      v_oh := COALESCE(v_oh, 0);

      IF v_oh < v_need THEN
        pp_product_id := (v_item->>'product_id')::UUID;
        include_product_code := v_inc.inc_code;
        needed := v_need;
        on_hand := v_oh;
        RETURN NEXT;
      END IF;
    END LOOP;
  END LOOP;
END;
$$;

-- ============================================
-- 131: Purchase badge counts (single RPC)
-- ============================================

CREATE OR REPLACE FUNCTION get_purchase_badge_counts()
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$
DECLARE
  v_pr_pending INT;
  v_pr_approved_no_po INT;
  v_po_waiting_gr INT;
BEGIN
  -- PR pending count
  SELECT COUNT(*) INTO v_pr_pending
  FROM inv_pr WHERE status = 'pending';

  -- Approved PRs that don't have a PO yet
  SELECT COUNT(*) INTO v_pr_approved_no_po
  FROM inv_pr pr
  WHERE pr.status = 'approved'
    AND NOT EXISTS (SELECT 1 FROM inv_po po WHERE po.pr_id = pr.id);

  -- POs waiting for GR (ordered or partial)
  SELECT COUNT(*) INTO v_po_waiting_gr
  FROM inv_po WHERE status IN ('ordered', 'partial');

  RETURN jsonb_build_object(
    'pr_pending', v_pr_pending,
    'pr_approved_no_po', v_pr_approved_no_po,
    'po_waiting_gr', v_po_waiting_gr
  );
END;
$$;

-- 154: Update auto FG conversion trigger to use roll_material_config_rms

CREATE OR REPLACE FUNCTION fn_auto_convert_rm_to_fg_on_movement()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cfg RECORD;
  v_fg_qty NUMERIC(12,2);
  v_unit_cost NUMERIC(14,4);
  v_movement_id UUID;
  v_note TEXT;
BEGIN
  IF NEW.movement_type NOT IN ('gr', 'adjust') THEN
    RETURN NEW;
  END IF;

  SELECT
    c.fg_product_id,
    c.sheets_per_roll,
    c.cost_per_sheet
  INTO v_cfg
  FROM roll_material_config_rms m
  JOIN roll_material_configs c ON c.id = m.config_id
  JOIN pr_products rm ON rm.id = m.rm_product_id
  JOIN pr_products fg ON fg.id = c.fg_product_id
  WHERE m.rm_product_id = NEW.product_id
    AND rm.product_type = 'RM'
    AND fg.product_type = 'FG'
    AND COALESCE(c.sheets_per_roll, 0) > 0
  ORDER BY c.updated_at DESC, c.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_fg_qty := ROUND(COALESCE(NEW.qty, 0) * v_cfg.sheets_per_roll, 2);
  IF COALESCE(v_fg_qty, 0) = 0 THEN
    RETURN NEW;
  END IF;

  v_note := format(
    'Auto FG from RM (%s): RM qty %s x sheets_per_roll %s',
    COALESCE(NEW.product_id::TEXT, '-'),
    COALESCE(NEW.qty::TEXT, '0'),
    COALESCE(v_cfg.sheets_per_roll::TEXT, '0')
  );

  INSERT INTO inv_stock_balances (product_id, on_hand, reserved, safety_stock)
  VALUES (v_cfg.fg_product_id, v_fg_qty, 0, 0)
  ON CONFLICT (product_id) DO UPDATE
    SET on_hand = inv_stock_balances.on_hand + v_fg_qty,
        updated_at = NOW();

  IF v_fg_qty > 0 THEN
    v_unit_cost := COALESCE(v_cfg.cost_per_sheet, fn_get_current_avg_cost(v_cfg.fg_product_id), 0);

    INSERT INTO inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by, unit_cost, total_cost
    )
    VALUES (
      v_cfg.fg_product_id,
      'roll_auto_fg',
      v_fg_qty,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id,
      v_note,
      NEW.created_by,
      v_unit_cost,
      v_fg_qty * v_unit_cost
    );

    INSERT INTO inv_stock_lots (
      product_id, qty_initial, qty_remaining, unit_cost, ref_type, ref_id
    )
    VALUES (
      v_cfg.fg_product_id,
      v_fg_qty,
      v_fg_qty,
      v_unit_cost,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id
    );
  ELSE
    INSERT INTO inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by
    )
    VALUES (
      v_cfg.fg_product_id,
      'roll_auto_fg',
      v_fg_qty,
      COALESCE(NEW.ref_type, 'roll_auto_fg'),
      NEW.ref_id,
      v_note,
      NEW.created_by
    )
    RETURNING id INTO v_movement_id;

    PERFORM fn_consume_stock_fifo(v_cfg.fg_product_id, ABS(v_fg_qty), v_movement_id);
  END IF;

  PERFORM fn_recalc_product_landed_cost(v_cfg.fg_product_id);

  RETURN NEW;
END;
$$;

-- เคลมซ้ำบิลเดิม: เลขบิล REQ รูปแบบ REQ{เลขบิลจัดส่ง}, REQ{เลขบิล}-2, REQ{เลขบิล}-3, ...

BEGIN;

CREATE OR REPLACE FUNCTION rpc_approve_claim_request(p_request_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $func$
DECLARE
  v_role           TEXT;
  v_uid            UUID := auth.uid();
  v_req            RECORD;
  v_ref            RECORD;
  v_claim_bill     TEXT;
  v_prefix         TEXT;
  v_i              INT := 1;
  v_order          JSONB;
  v_items          JSONB;
  v_new_order_id   UUID;
  v_item           JSONB;
  v_idx            INT := 0;
  v_item_uid       TEXT;
  v_pay_date       DATE;
  v_pay_time       TIME;
  v_sched          TIMESTAMPTZ;
BEGIN
  SELECT u.role INTO v_role FROM us_users u WHERE u.id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติเคลม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT * INTO v_req FROM or_claim_requests WHERE id = p_request_id FOR UPDATE;
  IF v_req.id IS NULL THEN RAISE EXCEPTION 'ไม่พบคำขอเคลม'; END IF;
  IF v_req.status <> 'pending' THEN
    RAISE EXCEPTION 'คำขอนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_req.status;
  END IF;

  SELECT * INTO v_ref FROM or_orders WHERE id = v_req.ref_order_id;
  IF v_ref.id IS NULL THEN RAISE EXCEPTION 'ไม่พบบิลอ้างอิง'; END IF;
  IF v_ref.status IS DISTINCT FROM 'จัดส่งแล้ว' THEN
    RAISE EXCEPTION 'บิลอ้างอิงต้องเป็นสถานะจัดส่งแล้ว (ปัจจุบัน: %)', v_ref.status;
  END IF;

  IF length(trim(both FROM COALESCE(v_ref.bill_no, ''))) = 0 THEN
    RAISE EXCEPTION 'บิลอ้างอิงไม่มีเลขบิล';
  END IF;

  v_prefix := 'REQ' || trim(both FROM v_ref.bill_no);
  v_claim_bill := v_prefix;
  WHILE EXISTS (SELECT 1 FROM or_orders o WHERE o.bill_no = v_claim_bill) LOOP
    v_i := v_i + 1;
    IF v_i > 10000 THEN
      RAISE EXCEPTION 'ไม่พบเลขบิลเคลมว่างสำหรับบิลอ้างอิงนี้';
    END IF;
    v_claim_bill := v_prefix || '-' || v_i::TEXT;
  END LOOP;

  v_order := v_req.proposed_snapshot->'order';
  IF v_order IS NULL OR jsonb_typeof(v_order) <> 'object' THEN
    RAISE EXCEPTION 'ข้อมูลคำขอไม่สมบูรณ์ (order)';
  END IF;

  v_items := v_req.proposed_snapshot->'items';
  IF v_items IS NULL OR jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'ต้องมีรายการสินค้าอย่างน้อย 1 รายการ';
  END IF;

  IF v_order->>'payment_date' IS NOT NULL AND length(trim(v_order->>'payment_date')) > 0 THEN
    v_pay_date := (v_order->>'payment_date')::DATE;
  ELSE
    v_pay_date := v_ref.payment_date;
  END IF;

  IF v_order->>'payment_time' IS NOT NULL AND length(trim(v_order->>'payment_time')) > 0 THEN
    v_pay_time := (v_order->>'payment_time')::TIME;
  ELSE
    v_pay_time := v_ref.payment_time;
  END IF;

  IF v_order->>'scheduled_pickup_at' IS NOT NULL AND length(trim(v_order->>'scheduled_pickup_at')) > 0 THEN
    v_sched := (v_order->>'scheduled_pickup_at')::TIMESTAMPTZ;
  ELSE
    v_sched := v_ref.scheduled_pickup_at;
  END IF;

  INSERT INTO or_orders (
    channel_code,
    customer_name,
    customer_address,
    channel_order_no,
    recipient_name,
    scheduled_pickup_at,
    price,
    shipping_cost,
    discount,
    total_amount,
    payment_method,
    promotion,
    payment_date,
    payment_time,
    status,
    admin_user,
    entry_date,
    bill_no,
    claim_type,
    claim_details,
    billing_details,
    packing_meta,
    work_order_name,
    work_order_id,
    shipped_by,
    shipped_time,
    tracking_number,
    requires_confirm_design
  ) VALUES (
    COALESCE(NULLIF(trim(both FROM v_order->>'channel_code'), ''), v_ref.channel_code),
    COALESCE(v_order->>'customer_name', v_ref.customer_name),
    COALESCE(v_order->>'customer_address', v_ref.customer_address),
    CASE
      WHEN v_order ? 'channel_order_no' THEN NULLIF(trim(both FROM v_order->>'channel_order_no'), '')::TEXT
      ELSE v_ref.channel_order_no
    END,
    CASE
      WHEN v_order ? 'recipient_name' THEN NULLIF(trim(both FROM v_order->>'recipient_name'), '')::TEXT
      ELSE v_ref.recipient_name
    END,
    v_sched,
    COALESCE((v_order->>'price')::NUMERIC, v_ref.price, 0),
    COALESCE((v_order->>'shipping_cost')::NUMERIC, v_ref.shipping_cost, 0),
    COALESCE((v_order->>'discount')::NUMERIC, v_ref.discount, 0),
    COALESCE((v_order->>'total_amount')::NUMERIC, v_ref.total_amount, 0),
    CASE
      WHEN v_order ? 'payment_method' THEN NULLIF(v_order->>'payment_method', '')::TEXT
      ELSE v_ref.payment_method
    END,
    CASE
      WHEN v_order ? 'promotion' THEN NULLIF(v_order->>'promotion', '')::TEXT
      ELSE v_ref.promotion
    END,
    v_pay_date,
    v_pay_time,
    COALESCE(NULLIF(trim(both FROM v_order->>'status'), ''), 'รอลงข้อมูล'),
    COALESCE(NULLIF(trim(both FROM v_order->>'admin_user'), ''), v_ref.admin_user),
    COALESCE(
      CASE WHEN v_order->>'entry_date' IS NOT NULL AND length(trim(v_order->>'entry_date')) > 0
        THEN (v_order->>'entry_date')::DATE END,
      CURRENT_DATE
    ),
    v_claim_bill,
    trim(both FROM v_req.claim_type),
    CASE WHEN v_order ? 'claim_details' THEN NULLIF(v_order->>'claim_details', '')::TEXT END,
    COALESCE(v_order->'billing_details', v_ref.billing_details),
    CASE WHEN v_order ? 'packing_meta' THEN v_order->'packing_meta' END,
    CASE WHEN v_order ? 'work_order_name' THEN NULLIF(trim(both FROM v_order->>'work_order_name'), '')::TEXT END,
    NULL,
    CASE WHEN v_order ? 'shipped_by' THEN NULLIF(trim(both FROM v_order->>'shipped_by'), '')::TEXT END,
    CASE
      WHEN v_order ? 'shipped_time' AND v_order->>'shipped_time' IS NOT NULL AND length(trim(v_order->>'shipped_time')) > 0
        THEN (v_order->>'shipped_time')::TIMESTAMPTZ
      ELSE v_ref.shipped_time
    END,
    CASE WHEN v_order ? 'tracking_number' THEN NULLIF(trim(both FROM v_order->>'tracking_number'), '')::TEXT
      ELSE v_ref.tracking_number
    END,
    COALESCE((v_order->>'requires_confirm_design')::BOOLEAN, v_ref.requires_confirm_design, TRUE)
  )
  RETURNING id INTO v_new_order_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) AS t(value)
  LOOP
    v_idx := v_idx + 1;
    v_item_uid := v_claim_bill || '-' || v_idx::TEXT;

    INSERT INTO or_order_items (
      order_id,
      item_uid,
      product_id,
      product_name,
      quantity,
      unit_price,
      ink_color,
      product_type,
      cartoon_pattern,
      line_pattern,
      font,
      line_1,
      line_2,
      line_3,
      no_name_line,
      is_free,
      notes,
      file_attachment
    ) VALUES (
      v_new_order_id,
      v_item_uid,
      NULLIF(trim(both FROM v_item->>'product_id'), '')::UUID,
      COALESCE(trim(both FROM v_item->>'product_name'), ''),
      COALESCE((v_item->>'quantity')::INT, 1),
      COALESCE((v_item->>'unit_price')::NUMERIC, 0),
      NULLIF(trim(both FROM v_item->>'ink_color'), '')::TEXT,
      COALESCE(NULLIF(trim(both FROM v_item->>'product_type'), '')::TEXT, 'ชั้น1'),
      NULLIF(trim(both FROM v_item->>'cartoon_pattern'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_pattern'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'font'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_1'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_2'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'line_3'), '')::TEXT,
      COALESCE((v_item->>'no_name_line')::BOOLEAN, FALSE),
      COALESCE((v_item->>'is_free')::BOOLEAN, FALSE),
      NULLIF(trim(both FROM v_item->>'notes'), '')::TEXT,
      NULLIF(trim(both FROM v_item->>'file_attachment'), '')::TEXT
    );
  END LOOP;

  UPDATE or_claim_requests
  SET status = 'approved',
      reviewed_by = v_uid,
      reviewed_at = NOW(),
      created_claim_order_id = v_new_order_id
  WHERE id = p_request_id;

  RETURN jsonb_build_object(
    'order_id', v_new_order_id,
    'bill_no', v_claim_bill
  );
END;
$func$;

COMMIT;

-- 256: Delete all product master data (superadmin only)
-- Requires transactional data to be cleared first (reset_only).

CREATE OR REPLACE FUNCTION erp_data_product_dependent_master_tables()
RETURNS TEXT[]
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT ARRAY[
    'pp_recipe_removes',
    'pp_recipe_includes',
    'pp_recipes',
    'roll_material_config_rms',
    'roll_material_configs',
    'qc_checklist_topic_products',
    'wh_sub_warehouse_products',
    'wh_sub_wms_map_spares',
    'wh_sub_wms_map_sources',
    'ac_inventory_epoch_openings',
    'pr_product_field_overrides',
    'pr_product_channel_prices'
  ];
$$;

CREATE OR REPLACE FUNCTION rpc_data_delete_all_products(
  p_confirm_text TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
DECLARE
  v_table TEXT;
  v_truncate_tables TEXT := '';
  v_product_count BIGINT;
  v_deleted BIGINT := 0;
  v_blockers JSONB;
BEGIN
  PERFORM erp_data_assert_superadmin();

  IF COALESCE(p_confirm_text, '') <> 'DELETE ALL PRODUCTS' THEN
    RAISE EXCEPTION 'ข้อความยืนยันไม่ถูกต้อง ต้องพิมพ์: DELETE ALL PRODUCTS';
  END IF;

  SELECT jsonb_build_object(
    'or_orders', COALESCE((SELECT COUNT(*) FROM or_orders), 0),
    'inv_stock_balances', COALESCE((SELECT COUNT(*) FROM inv_stock_balances), 0),
    'inv_stock_lots', COALESCE((SELECT COUNT(*) FROM inv_stock_lots), 0),
    'wms_orders', COALESCE((SELECT COUNT(*) FROM wms_orders), 0),
    'pp_production_orders', COALESCE((SELECT COUNT(*) FROM pp_production_orders), 0),
    'inv_po', COALESCE((SELECT COUNT(*) FROM inv_po), 0),
    'inv_pr', COALESCE((SELECT COUNT(*) FROM inv_pr), 0)
  )
  INTO v_blockers;

  IF (v_blockers->>'or_orders')::BIGINT > 0
    OR (v_blockers->>'inv_stock_balances')::BIGINT > 0
    OR (v_blockers->>'inv_stock_lots')::BIGINT > 0
    OR (v_blockers->>'wms_orders')::BIGINT > 0
    OR (v_blockers->>'pp_production_orders')::BIGINT > 0
    OR (v_blockers->>'inv_po')::BIGINT > 0
    OR (v_blockers->>'inv_pr')::BIGINT > 0
  THEN
    RAISE EXCEPTION 'ต้องล้างข้อมูลธุรกรรมก่อน (ใช้ ล้างข้อมูลอย่างเดียว) blockers: %', v_blockers::TEXT;
  END IF;

  SELECT COUNT(*) INTO v_product_count FROM pr_products;

  FOREACH v_table IN ARRAY erp_data_product_dependent_master_tables()
  LOOP
    IF to_regclass('public.' || v_table) IS NOT NULL THEN
      v_truncate_tables := v_truncate_tables || CASE WHEN v_truncate_tables = '' THEN '' ELSE ', ' END || format('%I', v_table);
    END IF;
  END LOOP;

  IF v_truncate_tables <> '' THEN
    EXECUTE 'TRUNCATE ' || v_truncate_tables;
  END IF;

  DELETE FROM pr_products WHERE id IS NOT NULL;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_products', v_deleted,
    'previous_product_count', v_product_count,
    'hr_policy', 'preserved',
    'note', 'pr_sellers และ master อื่นๆ ยังอยู่ — นำเข้าสินค้าใหม่ได้ทันที'
  );
END;
$$;

REVOKE ALL ON FUNCTION erp_data_product_dependent_master_tables() FROM PUBLIC;
REVOKE ALL ON FUNCTION rpc_data_delete_all_products(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION rpc_data_delete_all_products(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION rpc_data_delete_all_products(TEXT) TO service_role;

-- 257: Delete all seller master data (superadmin only)
-- Requires transactional data to be cleared first (same blockers as delete products).

CREATE OR REPLACE FUNCTION rpc_data_delete_all_sellers(
  p_confirm_text TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
DECLARE
  v_seller_count BIGINT;
  v_deleted BIGINT := 0;
  v_blockers JSONB;
BEGIN
  PERFORM erp_data_assert_superadmin();

  IF COALESCE(p_confirm_text, '') <> 'DELETE ALL SELLERS' THEN
    RAISE EXCEPTION 'ข้อความยืนยันไม่ถูกต้อง ต้องพิมพ์: DELETE ALL SELLERS';
  END IF;

  SELECT jsonb_build_object(
    'or_orders', COALESCE((SELECT COUNT(*) FROM or_orders), 0),
    'inv_stock_balances', COALESCE((SELECT COUNT(*) FROM inv_stock_balances), 0),
    'inv_stock_lots', COALESCE((SELECT COUNT(*) FROM inv_stock_lots), 0),
    'wms_orders', COALESCE((SELECT COUNT(*) FROM wms_orders), 0),
    'pp_production_orders', COALESCE((SELECT COUNT(*) FROM pp_production_orders), 0),
    'inv_po', COALESCE((SELECT COUNT(*) FROM inv_po), 0),
    'inv_pr', COALESCE((SELECT COUNT(*) FROM inv_pr), 0)
  )
  INTO v_blockers;

  IF (v_blockers->>'or_orders')::BIGINT > 0
    OR (v_blockers->>'inv_stock_balances')::BIGINT > 0
    OR (v_blockers->>'inv_stock_lots')::BIGINT > 0
    OR (v_blockers->>'wms_orders')::BIGINT > 0
    OR (v_blockers->>'pp_production_orders')::BIGINT > 0
    OR (v_blockers->>'inv_po')::BIGINT > 0
    OR (v_blockers->>'inv_pr')::BIGINT > 0
  THEN
    RAISE EXCEPTION 'ต้องล้างข้อมูลธุรกรรมก่อน (ใช้ ล้างข้อมูลอย่างเดียว) blockers: %', v_blockers::TEXT;
  END IF;

  SELECT COUNT(*) INTO v_seller_count FROM pr_sellers;

  DELETE FROM pr_sellers WHERE id IS NOT NULL;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_sellers', v_deleted,
    'previous_seller_count', v_seller_count,
    'hr_policy', 'preserved',
    'note', 'ชื่อผู้ขายในสินค้า (seller_name) ยังอยู่ — ซิงก์จากสินค้าหรือเพิ่มมือใหม่ได้'
  );
END;
$$;

REVOKE ALL ON FUNCTION rpc_data_delete_all_sellers(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION rpc_data_delete_all_sellers(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION rpc_data_delete_all_sellers(TEXT) TO service_role;

-- Allow work-order prefixes containing regex characters, such as "(เคลม)SPTR".
CREATE OR REPLACE FUNCTION rpc_next_work_order_name(
  p_prefix TEXT,
  p_date_part TEXT
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role TEXT;
  v_prefix TEXT;
  v_prefix_pattern TEXT;
  v_date TEXT;
  v_next INT;
  v_seed INT;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'order_staff', 'packing_staff', 'manager', 'production') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างเลขใบงาน';
  END IF;

  v_prefix := trim(both FROM coalesce(p_prefix,''));
  v_date := trim(both FROM coalesce(p_date_part,''));
  IF v_prefix = '' OR v_date = '' THEN
    RAISE EXCEPTION 'ข้อมูลไม่ครบ (prefix/date_part)';
  END IF;

  -- Escape PostgreSQL regular-expression metacharacters before matching
  -- existing names. The original prefix remains unchanged in the result.
  v_prefix_pattern := regexp_replace(v_prefix, '([.\\+*?\[\]^$(){}|])', '\\\1', 'g');

  PERFORM pg_advisory_xact_lock(hashtext('wo_seq:' || v_prefix || ':' || v_date));

  SELECT COALESCE(
    MAX((regexp_match(wo.work_order_name, ('^' || v_prefix_pattern || '-' || v_date || '-R([0-9]+)$')))[1]::int),
    0
  )
  INTO v_seed
  FROM or_work_orders wo
  WHERE wo.work_order_name ~ ('^' || v_prefix_pattern || '-' || v_date || '-R[0-9]+$')
    AND (
      wo.status IS DISTINCT FROM 'ยกเลิก'
      OR (
        EXISTS (
          SELECT 1 FROM plan_jobs pj
          WHERE pj.work_order_id = wo.id
            AND pj.is_production_voided = true
        )
        AND NOT fn_work_order_wms_fully_returned_or_cleared(wo.id)
      )
    );

  INSERT INTO or_work_order_sequences(prefix, date_part, last_r_no)
  VALUES (v_prefix, v_date, v_seed)
  ON CONFLICT (prefix, date_part)
  DO UPDATE SET
    last_r_no = EXCLUDED.last_r_no,
    updated_at = now();

  UPDATE or_work_order_sequences
  SET last_r_no = last_r_no + 1,
      updated_at = now()
  WHERE prefix = v_prefix AND date_part = v_date
  RETURNING last_r_no INTO v_next;

  RETURN v_prefix || '-' || v_date || '-R' || v_next::text;
END;
$$;

REVOKE ALL ON FUNCTION rpc_next_work_order_name(TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION rpc_next_work_order_name(TEXT, TEXT) TO authenticated;

-- Let Plan editors and production change a department's production line,
-- including after manpower has been locked. Keep worker assignments in sync.

CREATE OR REPLACE FUNCTION public.plan_update_job_line_assignment(
  p_plan_job_id text,
  p_department_name text,
  p_line_index integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_line_assignments jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.us_users u
    WHERE u.id = auth.uid()
      AND u.role IN ('superadmin', 'admin', 'production')
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขไลน์ผลิต';
  END IF;

  IF NULLIF(btrim(p_department_name), '') IS NULL OR p_line_index < 0 THEN
    RAISE EXCEPTION 'ข้อมูลไลน์ผลิตไม่ถูกต้อง';
  END IF;

  UPDATE public.plan_jobs
  SET line_assignments = jsonb_set(
    COALESCE(line_assignments, '{}'::jsonb),
    ARRAY[p_department_name],
    to_jsonb(p_line_index),
    true
  )
  WHERE id = p_plan_job_id
  RETURNING line_assignments INTO v_line_assignments;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบใบงาน';
  END IF;

  UPDATE public.plan_worker_assignments
  SET line_no = p_line_index + 1,
      updated_at = now()
  WHERE plan_job_id = p_plan_job_id
    AND department_name = p_department_name
    AND status <> 'cancelled';

  RETURN v_line_assignments;
END;
$$;

REVOKE ALL ON FUNCTION public.plan_update_job_line_assignment(text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.plan_update_job_line_assignment(text, text, integer) TO authenticated;

