-- Keep the browser permissions and database permissions aligned for the store role.
-- The row locks also prevent two concurrent actions from resolving the same borrow twice.
CREATE OR REPLACE FUNCTION public.approve_borrow_requisition(
  p_borrow_id UUID,
  p_user_id   UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
  v_item   RECORD;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  FOR v_item IN
    SELECT product_id, qty
    FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id
  LOOP
    INSERT INTO public.inv_stock_balances (product_id, on_hand, reserved, safety_stock)
    VALUES (v_item.product_id, 0, v_item.qty, 0)
    ON CONFLICT (product_id) DO UPDATE
      SET reserved = COALESCE(public.inv_stock_balances.reserved, 0) + v_item.qty;
  END LOOP;

  UPDATE public.wms_borrow_requisitions
  SET status = 'approved', approved_by = auth.uid(), approved_at = NOW()
  WHERE id = p_borrow_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.return_borrow_requisition(
  p_borrow_id UUID,
  p_items     JSONB,
  p_user_id   UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role        TEXT;
  v_status      TEXT;
  v_item        JSONB;
  v_product_id  UUID;
  v_return_qty  NUMERIC;
  v_borrow_item RECORD;
  v_all_done    BOOLEAN;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์รับคืนรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status NOT IN ('approved', 'partial_returned', 'overdue') THEN
    RAISE EXCEPTION 'ไม่สามารถคืนได้ (status: %)', v_status;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_return_qty := (v_item->>'return_qty')::NUMERIC;
    IF v_return_qty IS NULL OR v_return_qty <= 0 THEN CONTINUE; END IF;

    SELECT * INTO v_borrow_item
    FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id AND product_id = v_product_id
    FOR UPDATE;

    IF v_borrow_item IS NULL THEN CONTINUE; END IF;
    IF v_borrow_item.returned_qty + v_borrow_item.written_off_qty + v_return_qty > v_borrow_item.qty THEN
      RAISE EXCEPTION 'จำนวนคืนเกินจำนวนที่ยืม (สินค้า: %)', v_product_id;
    END IF;

    UPDATE public.wms_borrow_requisition_items
    SET returned_qty = returned_qty + v_return_qty
    WHERE id = v_borrow_item.id;

    UPDATE public.inv_stock_balances
    SET reserved = GREATEST(COALESCE(reserved, 0) - v_return_qty, 0)
    WHERE product_id = v_product_id;
  END LOOP;

  SELECT NOT EXISTS (
    SELECT 1 FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id
      AND (returned_qty + written_off_qty) < qty
  ) INTO v_all_done;

  IF v_all_done THEN
    UPDATE public.wms_borrow_requisitions
    SET status = 'returned', returned_at = NOW()
    WHERE id = p_borrow_id;
  ELSE
    UPDATE public.wms_borrow_requisitions
    SET status = 'partial_returned'
    WHERE id = p_borrow_id AND status <> 'partial_returned';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.write_off_borrow_requisition(
  p_borrow_id UUID,
  p_items     JSONB,
  p_user_id   UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role        TEXT;
  v_status      TEXT;
  v_item        JSONB;
  v_product_id  UUID;
  v_wo_qty      NUMERIC;
  v_borrow_item RECORD;
  v_movement_id UUID;
  v_all_done    BOOLEAN;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตัดรายการยืมเป็นของเสีย (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status NOT IN ('approved', 'partial_returned', 'overdue') THEN
    RAISE EXCEPTION 'ไม่สามารถตัดเป็นของเสียได้ (status: %)', v_status;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := (v_item->>'product_id')::UUID;
    v_wo_qty := (v_item->>'write_off_qty')::NUMERIC;
    IF v_wo_qty IS NULL OR v_wo_qty <= 0 THEN CONTINUE; END IF;

    SELECT * INTO v_borrow_item
    FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id AND product_id = v_product_id
    FOR UPDATE;

    IF v_borrow_item IS NULL THEN CONTINUE; END IF;
    IF v_borrow_item.returned_qty + v_borrow_item.written_off_qty + v_wo_qty > v_borrow_item.qty THEN
      RAISE EXCEPTION 'จำนวนตัดเสียเกินจำนวนที่ยืม (สินค้า: %)', v_product_id;
    END IF;

    UPDATE public.wms_borrow_requisition_items
    SET written_off_qty = written_off_qty + v_wo_qty
    WHERE id = v_borrow_item.id;

    UPDATE public.inv_stock_balances
    SET on_hand = COALESCE(on_hand, 0) - v_wo_qty,
        reserved = GREATEST(COALESCE(reserved, 0) - v_wo_qty, 0)
    WHERE product_id = v_product_id;

    INSERT INTO public.inv_stock_movements (
      product_id, movement_type, qty, ref_type, ref_id, note, created_by
    )
    VALUES (
      v_product_id, 'waste', -v_wo_qty,
      'wms_borrow_requisitions', p_borrow_id,
      'ตัดเป็นของเสีย (ยืมแล้วคืนไม่ได้)', auth.uid()
    )
    RETURNING id INTO v_movement_id;

    PERFORM public.fn_consume_stock_fifo(v_product_id, v_wo_qty, v_movement_id);
    PERFORM public.fn_recalc_product_landed_cost(v_product_id);
  END LOOP;

  SELECT NOT EXISTS (
    SELECT 1 FROM public.wms_borrow_requisition_items
    WHERE borrow_requisition_id = p_borrow_id
      AND (returned_qty + written_off_qty) < qty
  ) INTO v_all_done;

  IF v_all_done THEN
    UPDATE public.wms_borrow_requisitions
    SET status = 'written_off', returned_at = NOW()
    WHERE id = p_borrow_id;
  ELSE
    UPDATE public.wms_borrow_requisitions
    SET status = 'partial_returned'
    WHERE id = p_borrow_id AND status <> 'partial_returned';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_borrow_requisition(
  p_borrow_id UUID,
  p_user_id   UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role   TEXT;
  v_status TEXT;
BEGIN
  IF p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'ผู้ใช้งานไม่ตรงกับ session ปัจจุบัน';
  END IF;

  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'manager', 'store') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ปฏิเสธรายการยืม (role: %)', COALESCE(v_role, 'unknown');
  END IF;

  SELECT status INTO v_status
  FROM public.wms_borrow_requisitions
  WHERE id = p_borrow_id
  FOR UPDATE;

  IF v_status IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการยืม'; END IF;
  IF v_status <> 'pending' THEN
    RAISE EXCEPTION 'รายการนี้ไม่อยู่ในสถานะรออนุมัติ (status: %)', v_status;
  END IF;

  UPDATE public.wms_borrow_requisitions
  SET status = 'rejected', approved_by = auth.uid(), approved_at = NOW()
  WHERE id = p_borrow_id;
END;
$$;

COMMIT;

-- Sales confirms delivery only after Accounting approves and attaches a slip.
-- Keep approved refunds protected by the existing RLS policies: this RPC can
-- change only delivery metadata, never amounts, approval, or slip attachments.
BEGIN;

CREATE OR REPLACE FUNCTION public.mark_refund_slip_sent(p_refund_id uuid)
RETURNS TABLE(refund_slip_sent_at timestamptz, refund_slip_sent_by uuid)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor public.us_users%ROWTYPE;
  refund public.ac_refunds%ROWTYPE;
  order_owner text;
BEGIN
  SELECT * INTO actor FROM public.us_users WHERE id = auth.uid();
  IF actor.id IS NULL OR coalesce(actor.role, '') NOT IN ('sales-tr', 'sales-pump', 'admin', 'superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันส่งสลิปโอนคืน';
  END IF;

  SELECT * INTO refund FROM public.ac_refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ไม่พบรายการโอนคืน';
  END IF;
  SELECT btrim(o.admin_user) INTO order_owner FROM public.or_orders o WHERE o.id = refund.order_id;

  IF actor.role = 'sales-pump' AND NOT (
    coalesce(nullif(btrim(actor.username), '') = order_owner, false)
    OR coalesce(nullif(btrim(actor.email), '') = order_owner, false)
  ) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรายการโอนคืนของผู้อื่น';
  END IF;
  IF actor.role = 'sales-tr' AND NOT EXISTS (
    SELECT 1 FROM public.us_users u
    WHERE u.role = 'sales-tr' AND (
      nullif(btrim(u.username), '') = order_owner
      OR nullif(btrim(u.email), '') = order_owner
    )
  ) THEN
    RAISE EXCEPTION 'รายการโอนคืนนี้อยู่นอกทีม Sales TR';
  END IF;
  IF coalesce(refund.status, '') <> 'approved' OR coalesce(cardinality(refund.refund_slip_paths), 0) = 0 THEN
    RAISE EXCEPTION 'บัญชีต้องอนุมัติและแนบสลิปโอนคืนก่อน';
  END IF;

  -- Repeated confirmation preserves the original sender and timestamp.
  IF refund.refund_slip_sent_at IS NULL THEN
    UPDATE public.ac_refunds r
    SET refund_slip_sent_at = now(), refund_slip_sent_by = actor.id
    WHERE r.id = p_refund_id
    RETURNING r.* INTO refund;
  END IF;
  RETURN QUERY SELECT refund.refund_slip_sent_at, refund.refund_slip_sent_by;
END;
$$;

REVOKE ALL ON FUNCTION public.mark_refund_slip_sent(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mark_refund_slip_sent(uuid) TO authenticated;
NOTIFY pgrst, 'reload schema';
COMMIT;

-- Sales-first reconciliation, audited receipts, literal rules and combined Statements.


CREATE TABLE public.ac_order_receipt_certifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES public.or_orders(id),
  amount NUMERIC(18,2) NOT NULL CHECK (amount > 0),
  receipt_method TEXT NOT NULL CHECK (receipt_method IN ('cash', 'other', 'transfer_exception')),
  received_on DATE NOT NULL,
  reason TEXT NOT NULL CHECK (length(btrim(reason)) > 0),
  evidence_reference TEXT,
  certified_by UUID NOT NULL REFERENCES public.us_users(id),
  certified_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_by UUID REFERENCES public.us_users(id),
  revoked_at TIMESTAMPTZ,
  revoke_reason TEXT
);
CREATE INDEX ON public.ac_order_receipt_certifications(order_id);
ALTER TABLE public.ac_order_receipt_certifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_read ON public.ac_order_receipt_certifications FOR SELECT TO authenticated
USING (EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role IN ('superadmin','account')));

CREATE FUNCTION public.bank_certify_receipt(p_order_id UUID, p_amount NUMERIC, p_method TEXT,
  p_received_on DATE, p_reason TEXT, p_evidence TEXT DEFAULT NULL)
RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_id UUID; v_order public.or_orders; v_received NUMERIC;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id = auth.uid() AND role = 'superadmin') THEN
    RAISE EXCEPTION 'เฉพาะ superadmin สามารถรับรองเงินรับ';
  END IF;
  SELECT * INTO v_order FROM public.or_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_order.status,'') IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') THEN
    RAISE EXCEPTION 'บิลนี้ไม่สามารถรับรองเงินรับได้';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount,2)
     OR p_received_on IS NULL OR p_received_on > (now() AT TIME ZONE 'Asia/Bangkok')::DATE
     OR NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุยอดเงิน วันที่รับ และเหตุผลให้ถูกต้อง'; END IF;
  SELECT COALESCE((SELECT sum(allocated_amount) FROM public.ac_bank_reconciliation_allocations WHERE order_id=p_order_id),0)
    + COALESCE((SELECT sum(amount) FROM public.ac_order_receipt_certifications WHERE order_id=p_order_id AND revoked_at IS NULL),0)
    INTO v_received;
  IF v_received + p_amount > v_order.total_amount + 0.01 THEN RAISE EXCEPTION 'ยอดรับรองเกินยอดค้างของบิล กรุณาตรวจเงินที่จับคู่แล้ว'; END IF;
  INSERT INTO public.ac_order_receipt_certifications(order_id,amount,receipt_method,received_on,reason,evidence_reference,certified_by)
  VALUES(p_order_id,p_amount,p_method,p_received_on,btrim(p_reason),NULLIF(btrim(p_evidence),''),auth.uid()) RETURNING id INTO v_id;
  RETURN v_id;
END $$;

CREATE FUNCTION public.bank_revoke_receipt(p_id UUID, p_reason TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role='superadmin') THEN RAISE EXCEPTION 'เฉพาะ superadmin สามารถยกเลิกการรับรอง'; END IF;
  IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'กรุณาระบุเหตุผล'; END IF;
  PERFORM 1 FROM public.or_orders WHERE id=(SELECT order_id FROM public.ac_order_receipt_certifications WHERE id=p_id) FOR UPDATE;
  UPDATE public.ac_order_receipt_certifications SET revoked_by=auth.uid(),revoked_at=now(),revoke_reason=btrim(p_reason)
  WHERE id=p_id AND revoked_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'ไม่พบการรับรองที่ยังใช้งาน'; END IF;
END $$;

CREATE FUNCTION public.bank_sales_workspace(p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL,
 p_status TEXT DEFAULT 'pending',p_search TEXT DEFAULT '',p_channel TEXT DEFAULT '',p_method TEXT DEFAULT '',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_result JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 WITH base AS (
  SELECT o.id,o.bill_no,o.created_at,o.channel_code,o.payment_method,o.total_amount,
   COALESCE(a.amount,0) bank_received,COALESCE(c.amount,0) certified_received,
   COALESCE(s.amount,0)+COALESCE(m.amount,0) evidence_amount,COALESCE(c.cash,0) certified_cash,COALESCE(c.other,0) certified_other,
   s.payment_at,
   CASE WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>o.total_amount+0.01 THEN 'overpaid'
    WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>=o.total_amount-0.01 THEN CASE WHEN COALESCE(c.amount,0)>0 THEN 'certified' ELSE 'matched' END
    WHEN COALESCE(a.amount,0)+COALESCE(c.amount,0)>0 THEN 'partial'
    WHEN COALESCE(s.amount,0)+COALESCE(m.amount,0)>0 THEN 'waiting_bank' ELSE 'no_evidence' END reconciliation_state,
   CASE WHEN coverage.payment_count=0 OR coverage.has_unknown THEN 'unknown'
    WHEN coverage.uncovered THEN 'not_uploaded' ELSE 'covered' END statement_coverage
  FROM public.or_orders o
  LEFT JOIN LATERAL (SELECT sum(allocated_amount) amount FROM public.ac_bank_reconciliation_allocations WHERE order_id=o.id) a ON TRUE
  LEFT JOIN LATERAL (SELECT sum(amount) amount,sum(amount) FILTER(WHERE receipt_method='cash') cash,sum(amount) FILTER(WHERE receipt_method<>'cash') other FROM public.ac_order_receipt_certifications WHERE order_id=o.id AND revoked_at IS NULL) c ON TRUE
  LEFT JOIN LATERAL (SELECT sum(verified_amount) amount,max(easyslip_date) payment_at,max(NULLIF(easyslip_receiver_account,'')) receiver_account
    FROM public.ac_verified_slips WHERE order_id=o.id AND COALESCE(is_deleted,false)=false AND verified_amount>0 AND easyslip_date IS NOT NULL) s ON TRUE
  LEFT JOIN LATERAL (SELECT sum(transfer_amount) amount,max(CASE WHEN transfer_date ~ '^\d{4}-\d{2}-\d{2}$' THEN transfer_date::DATE END) payment_on
    FROM public.ac_manual_slip_checks WHERE order_id=o.id AND status='approved'
    AND NOT EXISTS (SELECT 1 FROM public.ac_verified_slips vs WHERE vs.order_id=o.id AND COALESCE(vs.is_deleted,false)=false AND vs.easyslip_date IS NOT NULL AND vs.verified_amount>0)) m ON TRUE
  LEFT JOIN LATERAL (
   SELECT count(*) payment_count,bool_or(p.payment_on IS NULL OR NOT EXISTS(
     SELECT 1 FROM public.bank_settings b WHERE
      (p.receiver_account IS NOT NULL AND right(regexp_replace(p.receiver_account,'\D','','g'),4)=right(regexp_replace(b.account_number,'\D','','g'),4)
       AND (p.bank_code IS NULL OR b.bank_code=p.bank_code))
      OR (p.receiver_account IS NULL AND EXISTS(SELECT 1 FROM public.bank_settings_channels bc WHERE bc.bank_setting_id=b.id AND bc.channel_code=o.channel_code))
    )) has_unknown,
    bool_or(EXISTS(SELECT 1 FROM public.bank_settings b WHERE
      ((p.receiver_account IS NOT NULL AND right(regexp_replace(p.receiver_account,'\D','','g'),4)=right(regexp_replace(b.account_number,'\D','','g'),4)
        AND (p.bank_code IS NULL OR b.bank_code=p.bank_code))
       OR (p.receiver_account IS NULL AND EXISTS(SELECT 1 FROM public.bank_settings_channels bc WHERE bc.bank_setting_id=b.id AND bc.channel_code=o.channel_code)))
      AND NOT EXISTS(SELECT 1 FROM public.ac_bank_statement_imports i WHERE i.bank_setting_id=b.id AND p.payment_on BETWEEN i.period_start AND i.period_end)
    )) uncovered
   FROM (
    SELECT (vs.easyslip_date AT TIME ZONE 'Asia/Bangkok')::DATE payment_on,
      NULLIF(regexp_replace(COALESCE(vs.easyslip_receiver_account,''),'\D','','g'),'') receiver_account,NULLIF(btrim(vs.easyslip_receiver_bank_id),'') bank_code
    FROM public.ac_verified_slips vs WHERE vs.order_id=o.id AND COALESCE(vs.is_deleted,false)=false AND vs.verified_amount>0 AND vs.easyslip_date IS NOT NULL
    UNION ALL
    SELECT CASE WHEN ms.transfer_date ~ '^\d{4}-\d{2}-\d{2}$' THEN ms.transfer_date::DATE END,NULL::TEXT,NULL::TEXT
    FROM public.ac_manual_slip_checks ms WHERE ms.order_id=o.id AND ms.status='approved'
   ) p
  ) coverage ON TRUE
  WHERE COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ')
   AND (p_from IS NULL OR o.created_at >= p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR o.created_at < (p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_channel='' OR o.channel_code=p_channel) AND (p_method='' OR COALESCE(o.payment_method,'')=p_method)
   AND (p_search='' OR strpos(lower(o.bill_no),lower(p_search))>0)
 ), filtered AS (SELECT * FROM base WHERE p_status='all' OR reconciliation_state=p_status
   OR p_status='pending' AND reconciliation_state IN ('partial','waiting_bank','no_evidence','overpaid')),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',(SELECT jsonb_build_object('bills',count(*),'sales',COALESCE(sum(total_amount),0),
   'bank',COALESCE(sum(bank_received),0),'certified',COALESCE(sum(certified_received),0),'cash',COALESCE(sum(certified_cash),0),'other_certified',COALESCE(sum(certified_other),0),'outstanding',COALESCE(sum(greatest(total_amount-bank_received-certified_received,0)),0)) FROM base),
  'channels',(SELECT COALESCE(jsonb_agg(channel_code),'[]'::JSONB) FROM (SELECT DISTINCT channel_code FROM public.or_orders WHERE COALESCE(status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') ORDER BY channel_code) channels),
  'states',COALESCE((SELECT jsonb_object_agg(reconciliation_state,n) FROM (SELECT reconciliation_state,count(*) n FROM base GROUP BY reconciliation_state) counts),'{}'::JSONB)) INTO v_result;
 RETURN v_result;
END $$;

CREATE FUNCTION public.bank_statement_workspace(p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL,p_bank UUID DEFAULT NULL,
 p_status TEXT DEFAULT 'all',p_search TEXT DEFAULT '',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_result JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 WITH base AS (SELECT t.*,b.bank_name,b.account_number,r.rule_name,r.match_keyword,
  COALESCE(r.is_active AND (r.bank_setting_id IS NULL OR r.bank_setting_id=t.bank_setting_id)
   AND strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(btrim(r.match_keyword)))>0,false) rule_valid
  FROM public.ac_bank_statement_transactions t JOIN public.bank_settings b ON b.id=t.bank_setting_id
  LEFT JOIN public.ac_bank_transaction_rules r ON r.id=t.classification_rule_id
  WHERE (p_from IS NULL OR t.transaction_at>=p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR t.transaction_at<(p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_bank IS NULL OR t.bank_setting_id=p_bank)
   AND (p_search='' OR strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(p_search))>0)),
 filtered AS (SELECT * FROM base WHERE p_status='all' OR reconciliation_status=p_status),
 page AS (SELECT * FROM filtered ORDER BY transaction_at DESC,id LIMIT 100 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',(SELECT jsonb_build_object('credit',COALESCE(sum(credit_amount),0),
   'matched',COALESCE(sum(credit_amount) FILTER(WHERE reconciliation_status='matched'),0),
   'other',COALESCE(sum(credit_amount) FILTER(WHERE reconciliation_status='ignored'),0),
   'unmatchedCount',count(*) FILTER(WHERE credit_amount>0 AND reconciliation_status='unmatched'),
   'ambiguousCount',count(*) FILTER(WHERE credit_amount>0 AND reconciliation_status='ambiguous')) FROM base)) INTO v_result;
 RETURN v_result;
END $$;

CREATE FUNCTION public.bank_workspace_diagnostics(p_transaction_ids UUID[])
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_diagnostics JSONB; v_candidates JSONB;
BEGIN
 PERFORM public.bank_reconciliation_require_authorized_role();
 SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::JSONB) INTO v_diagnostics
 FROM (SELECT DISTINCT import_id FROM public.ac_bank_statement_transactions WHERE id=ANY(p_transaction_ids)) i
 CROSS JOIN LATERAL public.bank_statement_match_diagnostics(i.import_id) d WHERE d.transaction_id=ANY(p_transaction_ids);
 SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::JSONB) INTO v_candidates
 FROM (SELECT DISTINCT import_id FROM public.ac_bank_statement_transactions WHERE id=ANY(p_transaction_ids)) i
 CROSS JOIN LATERAL public.bank_statement_match_candidate_lists(i.import_id) d WHERE d.transaction_id=ANY(p_transaction_ids);
 RETURN jsonb_build_object('diagnostics',v_diagnostics,'candidates',v_candidates);
END $$;

REVOKE ALL ON FUNCTION public.bank_workspace_diagnostics(UUID[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bank_workspace_diagnostics(UUID[]) TO authenticated;
REVOKE ALL ON FUNCTION public.bank_certify_receipt(UUID,NUMERIC,TEXT,DATE,TEXT,TEXT),public.bank_revoke_receipt(UUID,TEXT),
 public.bank_sales_workspace(DATE,DATE,TEXT,TEXT,TEXT,TEXT,INTEGER),public.bank_statement_workspace(DATE,DATE,UUID,TEXT,TEXT,INTEGER) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bank_certify_receipt(UUID,NUMERIC,TEXT,DATE,TEXT,TEXT),public.bank_revoke_receipt(UUID,TEXT),
 public.bank_sales_workspace(DATE,DATE,TEXT,TEXT,TEXT,TEXT,INTEGER),public.bank_statement_workspace(DATE,DATE,UUID,TEXT,TEXT,INTEGER) TO authenticated;

CREATE OR REPLACE FUNCTION public.bank_matching_rule(
  p_bank_setting_id UUID,
  p_transaction_type TEXT,
  p_channel TEXT,
  p_description TEXT,
  p_debit_amount NUMERIC,
  p_credit_amount NUMERIC
)
RETURNS public.ac_bank_transaction_rules
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT rule.*
  FROM public.ac_bank_transaction_rules rule
  WHERE rule.is_active = TRUE
    AND (rule.bank_setting_id IS NULL OR rule.bank_setting_id = p_bank_setting_id)
    AND (
      rule.direction = 'both'
      OR (rule.direction = 'credit' AND COALESCE(p_credit_amount, 0) > 0)
      OR (rule.direction = 'debit' AND COALESCE(p_debit_amount, 0) > 0)
    )
    AND strpos(lower(concat_ws(' ', p_transaction_type, p_channel, p_description)), lower(btrim(rule.match_keyword))) > 0
  ORDER BY
    CASE WHEN rule.bank_setting_id IS NOT NULL THEN 0 ELSE 1 END,
    rule.priority,
    length(rule.match_keyword) DESC,
    rule.created_at,
    rule.id
  LIMIT 1;
$$;


CREATE OR REPLACE FUNCTION public.tr_classify_bank_statement_transaction()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_rule public.ac_bank_transaction_rules;
BEGIN
  IF NEW.reconciliation_status = 'matched' THEN RETURN NEW; END IF;

  SELECT * INTO v_rule
  FROM public.bank_matching_rule(
    NEW.bank_setting_id,
    NEW.transaction_type,
    NEW.channel,
    NEW.description,
    NEW.debit_amount,
    NEW.credit_amount
  );

  IF v_rule.id IS NOT NULL THEN
    NEW.reconciliation_status := 'ignored';
    NEW.classification_rule_id := v_rule.id;
    NEW.classification_name := v_rule.classification_name;
    NEW.classified_at := now();
    NEW.classified_by := auth.uid();
  ELSIF NEW.reconciliation_status='ignored' THEN
    NEW.reconciliation_status := 'unmatched';
    NEW.classification_rule_id := NULL;
    NEW.classification_name := NULL;
    NEW.classified_at := NULL;
    NEW.classified_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


CREATE TABLE public.ac_bank_classification_audit (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL,
 old_rule_id UUID, old_name TEXT, old_status TEXT, new_rule_id UUID, new_name TEXT, new_status TEXT,
 actor_id UUID, changed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.ac_bank_classification_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY classification_audit_read ON public.ac_bank_classification_audit FOR SELECT TO authenticated
 USING(EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid() AND role IN ('superadmin','account')));
CREATE FUNCTION public.tr_audit_bank_classification() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF ROW(OLD.classification_rule_id,OLD.classification_name,OLD.reconciliation_status) IS DISTINCT FROM
 ROW(NEW.classification_rule_id,NEW.classification_name,NEW.reconciliation_status) AND (OLD.reconciliation_status='ignored' OR NEW.reconciliation_status='ignored') THEN
 INSERT INTO public.ac_bank_classification_audit(transaction_id,old_rule_id,old_name,old_status,new_rule_id,new_name,new_status,actor_id)
 VALUES(NEW.id,OLD.classification_rule_id,OLD.classification_name,OLD.reconciliation_status,NEW.classification_rule_id,NEW.classification_name,NEW.reconciliation_status,auth.uid());
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER trg_audit_bank_classification AFTER UPDATE ON public.ac_bank_statement_transactions
 FOR EACH ROW EXECUTE FUNCTION public.tr_audit_bank_classification();

CREATE OR REPLACE FUNCTION public.tr_sync_bank_rule_classification_name() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 UPDATE public.ac_bank_statement_transactions t
 SET reconciliation_status='unmatched',classification_rule_id=NULL,classification_name=NULL,classified_at=NULL,classified_by=NULL
 WHERE t.classification_rule_id=NEW.id AND t.reconciliation_status='ignored'
 AND (NOT NEW.is_active OR (NEW.bank_setting_id IS NOT NULL AND NEW.bank_setting_id<>t.bank_setting_id)
 OR NOT (NEW.direction='both' OR NEW.direction='credit' AND t.credit_amount>0 OR NEW.direction='debit' AND t.debit_amount>0)
 OR strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(btrim(NEW.match_keyword)))=0)
 AND NOT EXISTS(SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.transaction_id=t.id);
 UPDATE public.ac_bank_statement_transactions SET classification_name=NEW.classification_name
 WHERE classification_rule_id=NEW.id AND reconciliation_status='ignored' AND classification_name IS DISTINCT FROM NEW.classification_name;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_sync_bank_rule_classification_name ON public.ac_bank_transaction_rules;
CREATE TRIGGER trg_sync_bank_rule_classification_name AFTER UPDATE ON public.ac_bank_transaction_rules
 FOR EACH ROW EXECUTE FUNCTION public.tr_sync_bank_rule_classification_name();

-- Return invalid historical classifications to the review queue, retaining audit.
UPDATE public.ac_bank_statement_transactions t
SET reconciliation_status='unmatched',classification_rule_id=NULL,classification_name=NULL,classified_at=NULL,classified_by=NULL
WHERE t.reconciliation_status='ignored' AND NOT EXISTS(
 SELECT 1 FROM public.ac_bank_transaction_rules r WHERE r.id=t.classification_rule_id AND r.is_active
 AND (r.bank_setting_id IS NULL OR r.bank_setting_id=t.bank_setting_id)
 AND (r.direction='both' OR r.direction='credit' AND t.credit_amount>0 OR r.direction='debit' AND t.debit_amount>0)
 AND strpos(lower(concat_ws(' ',t.transaction_type,t.channel,t.description)),lower(btrim(r.match_keyword)))>0)
 AND NOT EXISTS(SELECT 1 FROM public.ac_bank_reconciliation_allocations a WHERE a.transaction_id=t.id);
CREATE OR REPLACE FUNCTION public.bank_reconciliation_save_rule(
  p_rule_id UUID,
  p_rule_name TEXT,
  p_match_keyword TEXT,
  p_classification_name TEXT,
  p_bank_setting_id UUID,
  p_apply_existing BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_rule_id UUID;
  v_applied INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตั้งค่าการจำแนกรายการธนาคาร';
  END IF;
  IF length(btrim(COALESCE(p_match_keyword, ''))) < 3 THEN
    RAISE EXCEPTION 'คำที่ใช้จับคู่ต้องมีอย่างน้อย 3 ตัวอักษร';
  END IF;
  IF btrim(COALESCE(p_classification_name, '')) = '' THEN
    RAISE EXCEPTION 'กรุณาระบุชื่อประเภทเงินรับ';
  END IF;
  IF p_bank_setting_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.bank_settings WHERE id = p_bank_setting_id AND is_active = TRUE)
  THEN
    RAISE EXCEPTION 'ไม่พบบัญชีธนาคารที่เปิดใช้งาน';
  END IF;

  IF p_rule_id IS NULL THEN
    INSERT INTO public.ac_bank_transaction_rules (
      rule_name, match_keyword, classification_name, bank_setting_id,
      direction, created_by, updated_at
    ) VALUES (
      COALESCE(NULLIF(btrim(p_rule_name), ''), btrim(p_classification_name)),
      btrim(p_match_keyword),
      btrim(p_classification_name),
      p_bank_setting_id,
      'credit',
      auth.uid(),
      now()
    )
    RETURNING id INTO v_rule_id;
  ELSE
    UPDATE public.ac_bank_transaction_rules
    SET rule_name = COALESCE(NULLIF(btrim(p_rule_name), ''), btrim(p_classification_name)),
        match_keyword = btrim(p_match_keyword),
        classification_name = btrim(p_classification_name),
        bank_setting_id = p_bank_setting_id,
        updated_at = now()
    WHERE id = p_rule_id
    RETURNING id INTO v_rule_id;
    IF v_rule_id IS NULL THEN RAISE EXCEPTION 'ไม่พบกฎที่ต้องการแก้ไข'; END IF;
  END IF;

  IF COALESCE(p_apply_existing, TRUE) AND EXISTS (SELECT 1 FROM public.ac_bank_transaction_rules WHERE id=v_rule_id AND is_active) THEN
    UPDATE public.ac_bank_statement_transactions transaction
    SET reconciliation_status = 'ignored',
        classification_rule_id = v_rule_id,
        classification_name = btrim(p_classification_name),
        classified_at = now(),
        classified_by = auth.uid()
    WHERE transaction.credit_amount > 0
      AND transaction.reconciliation_status IN ('unmatched', 'ambiguous')
      AND (p_bank_setting_id IS NULL OR transaction.bank_setting_id = p_bank_setting_id)
      AND strpos(lower(concat_ws(' ', transaction.transaction_type, transaction.channel, transaction.description)), lower(btrim(p_match_keyword))) > 0
      AND NOT EXISTS (
        SELECT 1 FROM public.ac_bank_reconciliation_allocations allocation
        WHERE allocation.transaction_id = transaction.id
      );
    GET DIAGNOSTICS v_applied = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object('rule_id', v_rule_id, 'applied_count', v_applied);
END;
$$;


