CREATE OR REPLACE FUNCTION public.tr_delivery_check_import(
  p_carrier TEXT,
  p_file_name TEXT,
  p_file_hash TEXT,
  p_sheet_name TEXT,
  p_pickup_date_from DATE,
  p_pickup_date_to DATE,
  p_warnings JSONB,
