SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_import_id UUID;
  v_item JSONB;
  v_order RECORD;
  v_candidate_count INTEGER;
  v_order_no TEXT;
  v_tracking_no TEXT;
  v_order_key TEXT;
  v_tracking_key TEXT;
  v_is_consignment BOOLEAN;
  v_match_status TEXT;
  v_match_method TEXT;
  v_match_detail TEXT;
  v_order_id UUID;
  v_source_count INTEGER := 0;
  v_matched_count INTEGER := 0;
  v_issue_count INTEGER := 0;
  v_consignment_count INTEGER := 0;
  v_system_only_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์นำเข้าไฟล์ตรวจสอบการส่ง';
  END IF;
  IF nullif(btrim(p_carrier), '') IS NULL THEN
    RAISE EXCEPTION 'กรุณาเลือกบริษัทขนส่ง';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'ไฟล์ไม่มีรายการสำหรับนำเข้า';
  END IF;

  INSERT INTO public.tr_delivery_check_imports (
    carrier, file_name, file_hash, sheet_name, pickup_date_from, pickup_date_to,
    source_row_count, warnings, uploaded_by
  ) VALUES (
    upper(btrim(p_carrier)), p_file_name, p_file_hash, p_sheet_name,
    p_pickup_date_from, p_pickup_date_to, jsonb_array_length(p_rows),
    coalesce(p_warnings, '[]'::JSONB), auth.uid()
  ) RETURNING id INTO v_import_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_rows)
  LOOP
    v_source_count := v_source_count + 1;
    v_order_no := nullif(btrim(coalesce(v_item->>'order_no', '')), '');
    v_tracking_no := nullif(btrim(coalesce(v_item->>'tracking_no', '')), '');
    v_order_key := public.tr_normalize_delivery_key(v_order_no);
    v_tracking_key := public.tr_normalize_delivery_key(v_tracking_no);
    v_is_consignment := coalesce((v_item->>'is_consignment')::BOOLEAN, false);
    v_match_status := 'unmatched';
    v_match_method := NULL;
    v_match_detail := NULL;
    v_order_id := NULL;

    IF v_is_consignment THEN
      v_match_status := 'consignment';
      v_consignment_count := v_consignment_count + 1;
    ELSIF v_tracking_key = '' THEN
      v_match_status := 'invalid';
      v_match_detail := 'ไม่มี Tracking No.';
      v_issue_count := v_issue_count + 1;
    ELSE
      SELECT count(*)
      INTO v_candidate_count
      FROM public.or_orders o
      WHERE COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.tr_normalize_delivery_key(o.tracking_number) = v_tracking_key;

      IF v_candidate_count = 1 THEN
        SELECT o.id, o.bill_no, o.channel_order_no, o.tracking_number
        INTO v_order
        FROM public.or_orders o
        WHERE COALESCE(o.status, '') <> 'ยกเลิก'
        AND public.tr_normalize_delivery_key(o.tracking_number) = v_tracking_key
        LIMIT 1;
        v_order_id := v_order.id;
        v_match_method := 'tracking_number';
        IF v_order_key <> '' AND v_order_key IN (
          public.tr_normalize_delivery_key(v_order.bill_no),
          public.tr_normalize_delivery_key(v_order.channel_order_no)
        ) THEN
          v_match_status := 'matched';
          v_matched_count := v_matched_count + 1;
        ELSE
          v_match_status := 'tracking_only';
          v_match_detail := 'Tracking ตรง แต่ Order No. ไม่ตรงกับเลขบิลในระบบ';
          v_issue_count := v_issue_count + 1;
        END IF;
      ELSIF v_candidate_count > 1 THEN
        v_match_status := 'ambiguous';
        v_match_detail := 'พบ Tracking ซ้ำในระบบมากกว่า 1 บิล';
        v_issue_count := v_issue_count + 1;
      ELSE
        SELECT count(*)
        INTO v_candidate_count
        FROM public.or_orders o
        WHERE COALESCE(o.status, '') <> 'ยกเลิก'
          AND v_order_key <> '' AND v_order_key IN (
          public.tr_normalize_delivery_key(o.bill_no),
          public.tr_normalize_delivery_key(o.channel_order_no)
        );

        IF v_candidate_count = 1 THEN
          SELECT o.id, o.bill_no, o.channel_order_no, o.tracking_number
          INTO v_order
          FROM public.or_orders o
          WHERE COALESCE(o.status, '') <> 'ยกเลิก'
          AND v_order_key <> '' AND v_order_key IN (
            public.tr_normalize_delivery_key(o.bill_no),
            public.tr_normalize_delivery_key(o.channel_order_no)
          )
          LIMIT 1;
          v_order_id := v_order.id;
          v_match_method := CASE
            WHEN v_order_key = public.tr_normalize_delivery_key(v_order.bill_no) THEN 'bill_no'
            ELSE 'channel_order_no'
          END;
          v_match_status := 'order_only';
          v_match_detail := 'Order No. ตรง แต่ Tracking ไม่ตรงกับระบบ';
          v_issue_count := v_issue_count + 1;
        ELSIF v_candidate_count > 1 THEN
          v_match_status := 'ambiguous';
          v_match_detail := 'พบ Order No. ซ้ำในระบบมากกว่า 1 บิล';
          v_issue_count := v_issue_count + 1;
        ELSE
          v_match_status := 'unmatched';
          v_match_detail := 'ไม่พบเลขพัสดุหรือเลขบิลในระบบ';
          v_issue_count := v_issue_count + 1;
        END IF;
      END IF;
    END IF;

    INSERT INTO public.tr_delivery_check_rows (
      import_id, source_kind, source_row_number, pickup_at,
      order_no, order_no_normalized, tracking_no, tracking_no_normalized,
      sender, consignee, consignee_phone, consignee_address,
      is_consignment, note, order_id, match_status, match_method, match_detail, raw_data
    ) VALUES (
      v_import_id, 'carrier', (v_item->>'source_row_number')::INTEGER,
      nullif(v_item->>'pickup_at', '')::TIMESTAMPTZ,
      v_order_no, v_order_key, v_tracking_no, v_tracking_key,
      nullif(v_item->>'sender', ''), nullif(v_item->>'consignee', ''),
      nullif(v_item->>'consignee_phone', ''), nullif(v_item->>'consignee_address', ''),
      v_is_consignment, nullif(v_item->>'note', ''), v_order_id,
      v_match_status, v_match_method, v_match_detail, coalesce(v_item->'raw_data', '{}'::JSONB)
    );
  END LOOP;

  UPDATE public.tr_delivery_check_rows r
  SET has_duplicate = true,
      match_detail = concat_ws(' / ', r.match_detail, 'Tracking ซ้ำในไฟล์')
  WHERE r.import_id = v_import_id
    AND r.source_kind = 'carrier'
    AND r.tracking_no_normalized <> ''
    AND EXISTS (
      SELECT 1 FROM public.tr_delivery_check_rows duplicate_row
      WHERE duplicate_row.import_id = r.import_id
        AND duplicate_row.source_kind = 'carrier'
        AND duplicate_row.tracking_no_normalized = r.tracking_no_normalized
        AND duplicate_row.id <> r.id
    );

  -- Add bills shipped by the selected carrier during the pickup-file dates but
  -- absent from the carrier file. Consignments never create a missing ERP bill.
  INSERT INTO public.tr_delivery_check_rows (
    import_id, source_kind, pickup_at, order_no, order_no_normalized,
    tracking_no, tracking_no_normalized, sender, consignee,
    consignee_phone, consignee_address, order_id, match_status, match_detail, raw_data
  )
  SELECT
    v_import_id, 'system', o.shipped_time, o.bill_no,
    public.tr_normalize_delivery_key(o.bill_no), o.tracking_number,
    public.tr_normalize_delivery_key(o.tracking_number), o.channel_code,
    coalesce(o.recipient_name, o.customer_name),
    nullif(o.billing_details->>'mobile_phone', ''), o.customer_address,
    o.id, 'system_only', 'ระบบระบุว่าส่งแล้ว แต่ไม่พบในไฟล์ขนส่ง',
    jsonb_build_object('bill_no', o.bill_no, 'channel_code', o.channel_code, 'shipped_time', o.shipped_time)
  FROM public.or_orders o
  LEFT JOIN public.channels c ON c.channel_code = o.channel_code
  WHERE o.status = 'จัดส่งแล้ว'
    AND coalesce(o.fulfillment_method, CASE WHEN coalesce(c.is_self_pickup, false) THEN 'self_pickup' ELSE 'shipping' END) = 'shipping'
    AND upper(coalesce(c.default_carrier, 'OTHER')) = upper(btrim(p_carrier))
    AND (o.shipped_time AT TIME ZONE 'Asia/Bangkok')::DATE BETWEEN p_pickup_date_from AND p_pickup_date_to
    AND NOT EXISTS (
      SELECT 1 FROM public.tr_delivery_check_rows r
      WHERE r.import_id = v_import_id AND r.order_id = o.id
    );

  GET DIAGNOSTICS v_system_only_count = ROW_COUNT;
  SELECT count(*)
  INTO v_issue_count
  FROM public.tr_delivery_check_rows
  WHERE import_id = v_import_id
    AND (match_status NOT IN ('matched', 'manual_match', 'consignment') OR has_duplicate);

  UPDATE public.tr_delivery_check_imports
  SET source_row_count = v_source_count,
      matched_count = v_matched_count,
      issue_count = v_issue_count,
      consignment_count = v_consignment_count,
      system_only_count = v_system_only_count,
      updated_at = now()
  WHERE id = v_import_id;

  RETURN jsonb_build_object(
    'import_id', v_import_id,
    'source_row_count', v_source_count,
    'matched_count', v_matched_count,
    'issue_count', v_issue_count,
    'consignment_count', v_consignment_count,
    'system_only_count', v_system_only_count
  );
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'ไฟล์นี้เคยนำเข้าสำหรับขนส่งรายนี้แล้ว';
END;
$$;

CREATE OR REPLACE FUNCTION public.tr_delivery_check_find_previous_duplicates(
  p_tracking_keys TEXT[]
)
RETURNS TABLE (
  tracking_no_normalized TEXT,
  tracking_no TEXT,
  previous_import_id UUID,
  previous_file_name TEXT,
  previous_carrier TEXT,
  previous_imported_at TIMESTAMPTZ,
  previous_pickup_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจประวัติไฟล์ขนส่ง';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (row.tracking_no_normalized)
    row.tracking_no_normalized,
    row.tracking_no,
    import.id,
    import.file_name,
    import.carrier,
    import.uploaded_at,
    row.pickup_at
  FROM public.tr_delivery_check_rows row
  JOIN public.tr_delivery_check_imports import ON import.id = row.import_id
  WHERE row.source_kind = 'carrier'
    AND row.tracking_no_normalized = ANY(coalesce(p_tracking_keys, ARRAY[]::TEXT[]))
  ORDER BY row.tracking_no_normalized, import.uploaded_at DESC, row.created_at DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.tr_delivery_check_delete_import(p_import_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_import public.tr_delivery_check_imports;
  v_row_count INTEGER;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ลบประวัติการนำเข้า';
  END IF;

  SELECT * INTO v_import FROM public.tr_delivery_check_imports WHERE id = p_import_id;
  IF v_import.id IS NULL THEN RAISE EXCEPTION 'ไม่พบประวัติการนำเข้าที่ต้องการลบ'; END IF;

  SELECT count(*) INTO v_row_count
  FROM public.tr_delivery_check_rows
  WHERE import_id = p_import_id;

  DELETE FROM public.tr_delivery_check_imports WHERE id = p_import_id;

  RETURN jsonb_build_object(
    'deleted_import_id', v_import.id,
    'file_name', v_import.file_name,
    'carrier', v_import.carrier,
    'deleted_row_count', v_row_count
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.tr_delivery_check_rebuild_system_only(p_import_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_issue_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ประมวลผลรายการตรวจสอบการส่ง';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tr_delivery_check_imports WHERE id = p_import_id) THEN
    RAISE EXCEPTION 'ไม่พบรอบนำเข้า';
  END IF;

  DELETE FROM public.tr_delivery_check_rows
  WHERE import_id = p_import_id AND source_kind = 'system';

  SELECT count(*) INTO v_issue_count
  FROM public.tr_delivery_check_rows row
  WHERE row.import_id = p_import_id
    AND row.source_kind = 'carrier'
    AND row.review_status = 'open'
    AND (
      row.match_status NOT IN ('matched', 'manual_match', 'consignment')
      OR row.has_duplicate
      OR row.has_previous_import
    );

  UPDATE public.tr_delivery_check_imports
  SET system_only_count = 0,
      issue_count = v_issue_count,
      updated_at = now()
  WHERE id = p_import_id;

  RETURN jsonb_build_object('system_only_count', 0, 'issue_count', v_issue_count);
END;
$$;

CREATE OR REPLACE FUNCTION public.tr_delivery_tracking_workspace(
 p_from DATE DEFAULT NULL,p_to DATE DEFAULT NULL,p_status TEXT DEFAULT 'all',
 p_search TEXT DEFAULT '',p_carrier TEXT DEFAULT '',p_channel TEXT DEFAULT '',
 p_date_basis TEXT DEFAULT 'created',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_result JSONB;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.us_users WHERE id=auth.uid()
  AND role IN ('superadmin','admin','admin-tr','sales-tr','packing_staff', 'account')) THEN
  RAISE EXCEPTION 'ไม่มีสิทธิ์ตรวจสอบการส่ง';
 END IF;
 IF p_date_basis NOT IN ('created','packed') THEN RAISE EXCEPTION 'วันที่กรองไม่ถูกต้อง'; END IF;
 WITH scoped AS (
  SELECT o.id,o.bill_no,o.channel_order_no,o.created_at,o.channel_code,o.tracking_number,
   o.recipient_name,o.customer_name,o.status erp_status,o.shipped_time packed_at,
   COALESCE(o.fulfillment_method='self_pickup',c.is_self_pickup,false) self_pickup
  FROM public.or_orders o LEFT JOIN public.channels c ON c.channel_code=o.channel_code
  WHERE o.created_at >= TIMESTAMPTZ '2026-09-01 00:00:00+07'
   AND COALESCE(o.channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY')
   AND o.fulfillment_method IS DISTINCT FROM 'self_pickup'
   AND NOT COALESCE(c.is_self_pickup,false)
   AND COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ')
   AND (p_from IS NULL OR CASE WHEN p_date_basis='packed' THEN o.shipped_time ELSE o.created_at END >= p_from::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_to IS NULL OR CASE WHEN p_date_basis='packed' THEN o.shipped_time ELSE o.created_at END < (p_to+1)::TIMESTAMP AT TIME ZONE 'Asia/Bangkok')
   AND (p_channel='' OR o.channel_code=p_channel)
   AND (p_search='' OR strpos(lower(concat_ws(' ',o.bill_no,o.channel_order_no,o.tracking_number,o.recipient_name,o.customer_name)),lower(p_search))>0)
 ), evidence AS (
  SELECT o.*,r.id source_id,r.import_id,r.file_name,r.carrier,r.pickup_at,r.tracking_no carrier_tracking,
   r.order_no carrier_order_no,r.raw_data,r.match_detail,r.match_status,r.has_duplicate,
   r.candidate_count,r.keys_match,r.review_status,
   COALESCE(NULLIF(btrim(r.raw_data->>'สถานะงานรับ'),''),'') pickup_status
  FROM scoped o LEFT JOIN LATERAL (
   SELECT d.*,i.file_name,i.carrier,i.uploaded_at,
    (SELECT count(*) FROM public.or_orders other WHERE
      (d.tracking_no_normalized<>'' AND public.tr_normalize_delivery_key(other.tracking_number)=d.tracking_no_normalized)
      OR (d.order_no_normalized<>'' AND (public.tr_normalize_delivery_key(other.bill_no)=d.order_no_normalized
       OR public.tr_normalize_delivery_key(other.channel_order_no)=d.order_no_normalized))) candidate_count,
    (d.match_status='manual_match' AND d.order_id=o.id OR
     (d.tracking_no_normalized<>'' AND d.tracking_no_normalized=public.tr_normalize_delivery_key(o.tracking_number)
      AND d.order_no_normalized<>'' AND d.order_no_normalized IN
       (public.tr_normalize_delivery_key(o.bill_no),public.tr_normalize_delivery_key(o.channel_order_no))
      AND (d.order_id IS NULL OR d.order_id=o.id))) keys_match
   FROM public.tr_delivery_check_rows d JOIN public.tr_delivery_check_imports i ON i.id=d.import_id
   WHERE d.source_kind='carrier' AND NOT d.is_consignment
    AND (d.order_id=o.id OR (d.tracking_no_normalized<>'' AND d.tracking_no_normalized=public.tr_normalize_delivery_key(o.tracking_number))
     OR (d.order_no_normalized<>'' AND d.order_no_normalized IN
       (public.tr_normalize_delivery_key(o.bill_no),public.tr_normalize_delivery_key(o.channel_order_no))))
   ORDER BY d.pickup_at DESC NULLS LAST,i.uploaded_at DESC,d.source_row_number DESC,d.id LIMIT 1
  ) r ON TRUE
 ), classified AS (
  SELECT e.*,CASE
   WHEN self_pickup THEN 'self_pickup'
   WHEN source_id IS NOT NULL AND (NOT keys_match OR has_duplicate OR (candidate_count<>1 AND match_status<>'manual_match')) THEN 'needs_review'
   WHEN source_id IS NOT NULL AND lower(pickup_status) IN ('รับพัสดุไม่สำเร็จ','รับไม่สำเร็จ','ยกเลิก') THEN 'pickup_issue'
   WHEN source_id IS NOT NULL AND lower(pickup_status) IN ('รับพัสดุแล้ว','รับพัสดุสำเร็จ','รับพัสดุเรียบร้อย','picked up','picked_up') THEN 'received'
   WHEN source_id IS NOT NULL AND pickup_status='ยังไม่ได้รับพัสดุ' THEN 'awaiting_pickup'
   WHEN source_id IS NOT NULL THEN 'carrier_recorded'
   WHEN packed_at IS NULL THEN 'pending_pack'
   WHEN public.tr_normalize_delivery_key(tracking_number)='' THEN 'no_tracking'
   ELSE 'awaiting_carrier' END delivery_state
  FROM evidence e
 ), base AS (SELECT * FROM classified WHERE p_carrier='' OR carrier=p_carrier),
 filtered AS (SELECT * FROM base WHERE p_status='all' OR delivery_state=p_status
  OR (p_status='issues' AND delivery_state IN ('needs_review','pickup_issue','carrier_recorded'))
  OR (p_status='pending' AND delivery_state NOT IN ('received','self_pickup'))),
 page AS (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET greatest(p_offset,0))
 SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(to_jsonb(page)-'raw_data') FROM page),'[]'::JSONB),
  'count',(SELECT count(*) FROM filtered),'summary',jsonb_build_object('bills',(SELECT count(*) FROM base),
   'states',COALESCE((SELECT jsonb_object_agg(delivery_state,n) FROM (SELECT delivery_state,count(*) n FROM base GROUP BY delivery_state) s),'{}'::JSONB)),
  'channels',(SELECT COALESCE(jsonb_agg(channel_code),'[]'::JSONB) FROM (SELECT DISTINCT o.channel_code FROM public.or_orders o LEFT JOIN public.channels ch ON ch.channel_code=o.channel_code
   WHERE COALESCE(o.channel_code,'') NOT IN ('SPTR','FSPTR','TTTR','LZTR','PGTR','WY')
   AND o.fulfillment_method IS DISTINCT FROM 'self_pickup' AND NOT COALESCE(ch.is_self_pickup,false)
   AND o.created_at>=TIMESTAMPTZ '2026-09-01 00:00:00+07' AND COALESCE(o.status,'') NOT IN ('ยกเลิก','รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ') ORDER BY o.channel_code) c),
  'carriers',(SELECT COALESCE(jsonb_agg(carrier),'[]'::JSONB) FROM (SELECT DISTINCT carrier FROM public.tr_delivery_check_imports ORDER BY carrier) c)) INTO v_result;
 RETURN v_result;
END $$;

CREATE OR REPLACE FUNCTION public.tr_delivery_check_review_row(
  p_row_id UUID,
  p_note TEXT,
  p_resolved BOOLEAN DEFAULT false
)
RETURNS public.tr_delivery_check_rows
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_row public.tr_delivery_check_rows;
  v_issue_count INTEGER := 0;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขผลตรวจสอบการส่ง';
  END IF;

  UPDATE public.tr_delivery_check_rows
  SET note = nullif(btrim(coalesce(p_note, '')), ''),
      review_status = CASE WHEN p_resolved THEN 'resolved' ELSE review_status END,
      reviewed_by = CASE WHEN p_resolved THEN auth.uid() ELSE reviewed_by END,
      reviewed_at = CASE WHEN p_resolved THEN now() ELSE reviewed_at END,
      updated_at = now()
  WHERE id = p_row_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RAISE EXCEPTION 'ไม่พบรายการตรวจสอบ'; END IF;

  SELECT count(*) INTO v_issue_count
  FROM public.tr_delivery_check_rows row
  WHERE row.import_id = v_row.import_id
    AND row.source_kind = 'carrier'
    AND row.review_status = 'open'
    AND (
      row.match_status NOT IN ('matched', 'manual_match', 'consignment')
      OR row.has_duplicate
      OR row.has_previous_import
    );

  UPDATE public.tr_delivery_check_imports
  SET issue_count = v_issue_count,
      updated_at = now()
  WHERE id = v_row.import_id;

  RETURN v_row;
END;
$$;

CREATE OR REPLACE FUNCTION public.tr_delivery_check_move_to_review(p_row_id UUID, p_note TEXT)
RETURNS public.tr_delivery_check_rows
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
AS $$
DECLARE
  v_role TEXT;
  v_row public.tr_delivery_check_rows;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin', 'admin', 'admin-tr', 'sales-tr', 'packing_staff', 'account') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์แก้ไขผลตรวจสอบการส่ง';
  END IF;
  SELECT * INTO v_row FROM public.tr_delivery_check_rows WHERE id = p_row_id FOR UPDATE;
  IF v_row.id IS NULL OR v_row.source_kind <> 'carrier' OR NOT v_row.is_consignment THEN
    RAISE EXCEPTION 'รายการนี้ไม่ใช่รายการฝากส่ง';
  END IF;
  -- Serialize summary refreshes for this import.
  PERFORM 1 FROM public.tr_delivery_check_imports WHERE id = v_row.import_id FOR UPDATE;
  UPDATE public.tr_delivery_check_rows
  SET is_consignment = false, match_status = 'unmatched', match_method = 'manual_review',
      match_detail = 'เจ้าหน้าที่เปลี่ยนจากฝากส่งเป็นต้องตรวจ',
      note = nullif(btrim(coalesce(p_note, '')), ''), review_status = 'open',
      reviewed_by = NULL, reviewed_at = NULL, updated_at = now()
  WHERE id = p_row_id RETURNING * INTO v_row;
  UPDATE public.tr_delivery_check_imports i
  SET consignment_count = (SELECT count(*) FROM public.tr_delivery_check_rows r WHERE r.import_id = i.id AND r.source_kind = 'carrier' AND r.match_status = 'consignment'), updated_at = now()
  WHERE i.id = v_row.import_id;
  PERFORM public.tr_delivery_check_rebuild_system_only(v_row.import_id);
  RETURN v_row;
END;
$$;

-- Keep cost column grants and masked views unchanged. Only this guarded write
-- runs with owner privileges; it returns counts, never product/cost records.
BEGIN;
CREATE FUNCTION public.rpc_import_products(p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
AS $$
DECLARE
  item jsonb;
  product public.pr_products%ROWTYPE;
  v_id uuid;
  v_inserted integer := 0;
  v_updated integer := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.us_users
    WHERE id = auth.uid() AND role = 'superadmin' AND is_active IS TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'เฉพาะ superadmin ที่เปิดใช้งานเท่านั้นที่นำเข้าสินค้าได้';
  END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'ข้อมูลนำเข้าต้องเป็นรายการสินค้า';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) x
    GROUP BY lower(btrim(x->>'product_code')) HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'รหัสสินค้าซ้ำในรายการนำเข้า';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_items) ORDER BY value->>'product_code' LOOP
    -- Whitelist writable fields below; payload IDs and stock/cost metadata
    -- cannot overwrite existing records outside the import template.
    product := jsonb_populate_record(NULL::public.pr_products, item);
    product.product_code := btrim(product.product_code);
    product.product_name := btrim(product.product_name);
    product.product_type := coalesce(nullif(product.product_type, ''), 'FG');
    product.unit_name := coalesce(nullif(btrim(product.unit_name), ''), 'ชิ้น');
    product.unit_multiplier := coalesce(product.unit_multiplier, 1);
    product.unit_cost := coalesce(product.unit_cost, 0);
    IF coalesce(product.product_code, '') = '' OR coalesce(product.product_name, '') = ''
      OR product.product_type NOT IN ('FG', 'RM', 'PP')
      OR product.unit_multiplier <= 0 OR product.unit_cost < 0
      OR product.unit_cost::text IN ('NaN', 'Infinity', '-Infinity')
      OR product.unit_multiplier::text IN ('NaN', 'Infinity', '-Infinity')
      OR product.order_point_days < 0 THEN
      RAISE EXCEPTION 'ข้อมูลสินค้าไม่ถูกต้อง: %', product.product_code;
    END IF;
    IF jsonb_typeof(item->'channel_prices') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'ราคาช่องทางไม่ถูกต้อง: %', product.product_code;
    END IF;
    v_id := NULL;
    INSERT INTO public.pr_products (
      product_code, product_name, seller_name, product_name_cn, order_point,
      order_point_days, product_category, product_type, rubber_code,
      storage_location, unit_cost, unit_name, unit_multiplier, is_active
    ) VALUES (
      product.product_code, product.product_name, product.seller_name, product.product_name_cn,
      product.order_point, product.order_point_days, product.product_category, product.product_type,
      product.rubber_code, product.storage_location, product.unit_cost, product.unit_name,
      product.unit_multiplier, true
    ) ON CONFLICT (product_code) DO NOTHING RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      v_inserted := v_inserted + 1;
    ELSE
      UPDATE public.pr_products SET
        product_name = product.product_name, seller_name = product.seller_name,
        product_name_cn = product.product_name_cn, order_point = product.order_point,
        order_point_days = product.order_point_days, product_category = product.product_category,
        product_type = product.product_type, rubber_code = product.rubber_code,
        storage_location = product.storage_location, unit_cost = product.unit_cost,
        unit_name = product.unit_name, unit_multiplier = product.unit_multiplier
      WHERE product_code = product.product_code RETURNING id INTO v_id;
      v_updated := v_updated + 1;
    END IF;
    DELETE FROM public.pr_product_channel_prices WHERE product_id = v_id;
    INSERT INTO public.pr_product_channel_prices (product_id, channel_code, sale_price)
      SELECT v_id, key, value::numeric FROM jsonb_each_text(item->'channel_prices');
  END LOOP;
  RETURN jsonb_build_object('inserted', v_inserted, 'updated', v_updated);
END;
$$;
REVOKE ALL ON FUNCTION public.rpc_import_products(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_import_products(jsonb) TO authenticated;
NOTIFY pgrst, 'reload schema';
COMMIT;

-- Personal opening rights are the common source for HR and payroll.
-- No request, entitlement record, or payroll snapshot is modified here.

CREATE OR REPLACE FUNCTION public.get_employee_leave_summary(p_employee_id UUID, p_year INT)
RETURNS JSONB AS $$
DECLARE result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'balances', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', t.id,
        'leave_type_id', t.id,
        'leave_type_name', t.name,
        'entitled_days', CASE WHEN o.id IS NOT NULL THEN o.opening_remaining_days ELSE COALESCE(t.max_days_per_year, 0) END,
        'used_days', COALESCE(u.used, 0),
        'carried_days', 0,
        'remaining', GREATEST(0, CASE WHEN o.id IS NOT NULL THEN o.opening_remaining_days ELSE COALESCE(t.max_days_per_year, 0) END - COALESCE(u.used, 0)),
        'opening_effective_date', o.effective_date
      ) ORDER BY t.name)
      FROM public.hr_leave_types t
      LEFT JOIN public.hr_employee_opening_leave_balances o
        ON o.leave_type_id = t.id AND o.employee_id = p_employee_id AND o.year = p_year
        AND o.effective_date <= CASE WHEN p_year=EXTRACT(YEAR FROM now() AT TIME ZONE 'Asia/Bangkok')::int THEN (now() AT TIME ZONE 'Asia/Bangkok')::date ELSE make_date(p_year,12,31) END
      LEFT JOIN LATERAL (
        SELECT SUM(r.total_days) AS used
        FROM public.hr_leave_requests r
        WHERE r.employee_id = p_employee_id
          AND r.leave_type_id = t.id
          AND r.status = 'approved'
          AND EXTRACT(YEAR FROM r.start_date) = p_year
          AND (o.id IS NULL OR r.start_date >= o.effective_date)
      ) u ON TRUE
    ), '[]'::jsonb),
    'recent_requests', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', r.id, 'leave_type_name', t.name, 'start_date', r.start_date,
        'end_date', r.end_date, 'total_days', r.total_days, 'leave_mode', r.leave_mode,
        'start_time', r.start_time, 'end_time', r.end_time, 'total_hours', r.total_hours,
        'status', r.status, 'reason', r.reason, 'medical_cert_url', r.medical_cert_url,
        'created_at', r.created_at
      ) ORDER BY r.created_at DESC)
      FROM public.hr_leave_requests r
      JOIN public.hr_leave_types t ON t.id = r.leave_type_id
      WHERE r.employee_id = p_employee_id AND EXTRACT(YEAR FROM r.start_date) = p_year
    ), '[]'::jsonb),
    'pending_count', (SELECT count(*) FROM public.hr_leave_requests WHERE employee_id = p_employee_id AND status = 'pending')
  ) INTO result;
  RETURN result;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public;


-- Only annual vacation is restricted. Other categories retain the approved-overage workflow.
CREATE OR REPLACE FUNCTION public.hr_guard_vacation_entitlement()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_name text; v_entitled numeric; v_effective date; v_used numeric; v_year int;
BEGIN
  IF NEW.status NOT IN ('pending','approved') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.employee_id IS NOT DISTINCT FROM OLD.employee_id
     AND NEW.leave_type_id IS NOT DISTINCT FROM OLD.leave_type_id
     AND NEW.start_date IS NOT DISTINCT FROM OLD.start_date
     AND NEW.end_date IS NOT DISTINCT FROM OLD.end_date
     AND NEW.total_days IS NOT DISTINCT FROM OLD.total_days
     AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  SELECT name,max_days_per_year INTO v_name,v_entitled FROM hr_leave_types WHERE id=NEW.leave_type_id;
  IF btrim(v_name) IS DISTINCT FROM 'ลาพักร้อน' THEN RETURN NEW; END IF;
  IF EXTRACT(YEAR FROM NEW.start_date)<>EXTRACT(YEAR FROM NEW.end_date) THEN
    RAISE EXCEPTION 'กรุณาแยกใบลาพักร้อนตามปีที่ลา';
  END IF;
  v_year:=EXTRACT(YEAR FROM NEW.start_date)::int;
  PERFORM pg_advisory_xact_lock(hashtextextended('vacation:'||NEW.employee_id::text,0));
  v_effective:=make_date(v_year,1,1);
  SELECT opening_remaining_days,effective_date INTO v_entitled,v_effective
  FROM hr_employee_opening_leave_balances
  WHERE employee_id=NEW.employee_id AND leave_type_id=NEW.leave_type_id
    AND year=v_year AND effective_date<=NEW.start_date;
  IF NOT FOUND THEN
    SELECT COALESCE(max_days_per_year,0) INTO v_entitled FROM hr_leave_types WHERE id=NEW.leave_type_id;
    v_effective:=make_date(v_year,1,1);
  END IF;
  SELECT COALESCE(sum(total_days),0) INTO v_used FROM hr_leave_requests
  WHERE employee_id=NEW.employee_id AND leave_type_id=NEW.leave_type_id
    AND status IN ('pending','approved') AND id IS DISTINCT FROM NEW.id
    AND start_date>=v_effective AND start_date<make_date(v_year+1,1,1);
  IF NEW.total_days>GREATEST(0,v_entitled-v_used) THEN
    RAISE EXCEPTION 'สิทธิ์ลาพักร้อนไม่เพียงพอ: ขอ % วัน คงเหลือที่ขอได้ % วัน (หักคำขอรออนุมัติแล้ว)',NEW.total_days,GREATEST(0,v_entitled-v_used);
  END IF;
  RETURN NEW;
END;
$$;
-- Run after the existing working-day calculation triggers.
CREATE TRIGGER zz_hr_guard_vacation_entitlement BEFORE INSERT OR UPDATE ON public.hr_leave_requests
FOR EACH ROW EXECUTE FUNCTION public.hr_guard_vacation_entitlement();

NOTIFY pgrst,'reload schema';

-- AFTER ROW triggers see every bill linked by the bulk UPDATE. Previously each
-- bill therefore scanned the whole work order again, before the RPC's final scan.
-- Defer only that trigger for this RPC's new UUID; keep one authoritative WMS
-- pass after all links and the plan row exist. Stock/FIFO functions are unchanged.
BEGIN;

CREATE OR REPLACE FUNCTION public.trg_or_orders_try_auto_non_pick()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v_nm TEXT;
BEGIN
  IF NEW.work_order_id IS NOT NULL
     AND current_setting('app.defer_auto_wms_work_order_id',true)=NEW.work_order_id::TEXT THEN
    RETURN NEW;
  END IF;
  v_nm:=trim(both FROM coalesce(NEW.work_order_name,''));
  IF v_nm='' THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE'
     AND trim(both FROM coalesce(OLD.work_order_name,'')) IS NOT DISTINCT FROM v_nm THEN
    RETURN NEW;
  END IF;
  PERFORM public.fn_wms_try_auto_consume_non_pick(v_nm);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_create_work_order_with_plan(
  p_work_order_name TEXT,p_order_ids UUID[],p_plan_job_id TEXT,p_plan_date TEXT,
  p_cut TEXT,p_qty JSONB,p_order_index INTEGER
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE
  v_role TEXT; v_work_order_id UUID; v_requested INT; v_locked INT; v_auto_end TIMESTAMPTZ;
  v_previous_deferred_work_order TEXT;
BEGIN
  SELECT role INTO v_role FROM public.us_users WHERE id=auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('superadmin','admin','order_staff','packing_staff','manager','production') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์สร้างใบงาน';
  END IF;
  IF NULLIF(BTRIM(COALESCE(p_work_order_name,'')),'') IS NULL
     OR NULLIF(BTRIM(COALESCE(p_plan_job_id,'')),'') IS NULL
     OR NULLIF(BTRIM(COALESCE(p_plan_date,'')),'') IS NULL
     OR COALESCE(CARDINALITY(p_order_ids),0)=0 THEN
    RAISE EXCEPTION 'ข้อมูลสร้างใบงานไม่ครบ';
  END IF;
  v_requested:=(SELECT COUNT(DISTINCT id) FROM UNNEST(p_order_ids) AS requested(id));
  PERFORM 1 FROM public.or_orders WHERE id=ANY(p_order_ids) ORDER BY id FOR UPDATE;
  SELECT COUNT(*) INTO v_locked FROM public.or_orders
  WHERE id=ANY(p_order_ids) AND work_order_id IS NULL
    AND (
      status IN ('ใบสั่งงาน','คอนเฟิร์มแล้ว','เสร็จสิ้น','ย้ายจากใบงาน')
      OR (status='ตรวจสอบแล้ว' AND UPPER(BTRIM(COALESCE(channel_code,'')))='WY')
    );
  IF v_locked<>v_requested THEN
    RAISE EXCEPTION 'มีบิลบางรายการไม่อยู่ในคิวหรือถูกนำไปสร้างใบงานแล้ว กรุณารีเฟรช';
  END IF;

  INSERT INTO public.or_work_orders(work_order_name,status,order_count)
  VALUES(BTRIM(p_work_order_name),'กำลังผลิต',v_requested)
  RETURNING id INTO v_work_order_id;

  v_previous_deferred_work_order:=current_setting('app.defer_auto_wms_work_order_id',true);
  PERFORM set_config('app.defer_auto_wms_work_order_id',v_work_order_id::TEXT,true);
  UPDATE public.or_orders SET
    work_order_id=v_work_order_id,work_order_name=BTRIM(p_work_order_name),
    plan_released_from_work_order=NULL,plan_released_from_work_order_id=NULL,plan_released_at=NULL,
    status=CASE WHEN status='ย้ายจากใบงาน' THEN 'ใบสั่งงาน' ELSE status END
  WHERE id=ANY(p_order_ids);
  -- Restore before any other work; PostgreSQL also rolls this local setting
  -- back together with the statement if a validation/stock trigger raises.
  PERFORM set_config('app.defer_auto_wms_work_order_id',COALESCE(v_previous_deferred_work_order,''),true);

  INSERT INTO public.plan_jobs(id,date,name,work_order_id,cut,qty,tracks,line_assignments,
    manual_plan_starts,locked_plans,order_index)
  VALUES(BTRIM(p_plan_job_id),BTRIM(p_plan_date),BTRIM(p_work_order_name),v_work_order_id,p_cut,
    COALESCE(p_qty,'{}'::JSONB),'{}','{}','{}','{}',COALESCE(p_order_index,0));

  PERFORM public.fn_wms_try_auto_consume_non_pick(p_work_order_name);
  IF NOT EXISTS (
    SELECT 1 FROM public.or_orders o JOIN public.or_order_items oi ON oi.order_id=o.id
    JOIN public.pr_products p ON p.id=oi.product_id
    WHERE o.work_order_id=v_work_order_id AND NOT COALESCE(oi.is_detail_row,false)
      AND public.fn_wms_item_fulfillment_mode(p.id,p.product_category::TEXT)='warehouse_pick'
  ) THEN
    SELECT MAX(end_time) INTO v_auto_end FROM public.wms_orders WHERE work_order_id=v_work_order_id;
    v_auto_end:=COALESCE(v_auto_end,NOW());
    PERFORM public.merge_plan_tracks_by_work_order_id(v_work_order_id,'เบิก',jsonb_build_object(
      'หยิบของ',jsonb_build_object('start_if_null',v_auto_end,'end',v_auto_end),
      'ส่งมอบ',jsonb_build_object('start_if_null',v_auto_end,'end',v_auto_end)
    ));
  END IF;
  RETURN jsonb_build_object('success',true,'work_order_id',v_work_order_id,'work_order_name',BTRIM(p_work_order_name));
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_create_work_order_with_plan(TEXT,UUID[],TEXT,TEXT,TEXT,JSONB,INTEGER) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rpc_create_work_order_with_plan(TEXT,UUID[],TEXT,TEXT,TEXT,JSONB,INTEGER) TO authenticated;

COMMIT;

-- Match the daily sheet's work-order classification and completion-time fallback,
-- with an exact audit cutoff instead of an end-of-day cutoff. Definer rights are
-- needed because auditors may read Audit but cannot read raw WMS records.
CREATE OR REPLACE FUNCTION public.fn_audit_sub_warehouse_snapshot(p_product_id uuid, p_at timestamptz)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
  WITH ledger AS (
    SELECT m.sub_warehouse_id,sum(m.qty_delta) qty
    FROM public.wh_sub_warehouse_stock_moves m
    WHERE m.product_id=p_product_id AND m.created_at<=p_at
    GROUP BY m.sub_warehouse_id
  ), warehouse_ids AS (
    SELECT a.sub_warehouse_id FROM public.wh_sub_warehouse_products a
    WHERE a.product_id=p_product_id AND a.created_at<=p_at
    UNION SELECT b.sub_warehouse_id FROM ledger b WHERE b.qty<>0
  ), mappings AS (
    SELECT ids.sub_warehouse_id,g.id group_id
    FROM warehouse_ids ids
    JOIN public.wh_sub_wms_map_groups g
      ON (g.sub_warehouse_id IS NULL OR g.sub_warehouse_id=ids.sub_warehouse_id)
      AND g.created_at<=p_at
    JOIN public.wh_sub_wms_map_spares s ON s.group_id=g.id AND s.product_id=p_product_id
  ), usage_codes AS (
    SELECT p.product_code FROM public.pr_products p WHERE p.id=p_product_id
    UNION
    SELECT p.product_code FROM mappings g
    JOIN public.wh_sub_wms_map_sources s ON s.group_id=g.group_id
    JOIN public.pr_products p ON p.id=s.product_id
  ), relevant_orders AS MATERIALIZED (
    SELECT wms.* FROM public.wms_orders wms
    JOIN usage_codes codes ON codes.product_code::text=wms.product_code::text
    WHERE wms.status='correct'
  ), summary_times AS (
    SELECT btrim(s.order_id) order_id,min(s.checked_at) checked_at
    FROM public.wms_order_summaries s
    WHERE btrim(s.order_id) IN (SELECT btrim(r.order_id) FROM relevant_orders r)
    GROUP BY btrim(s.order_id)
  ), work_names AS MATERIALIZED (
    SELECT DISTINCT btrim(COALESCE(o.work_order_name,'')) name FROM public.or_orders o
  ), usage_rows AS (
    SELECT wms.product_code,wms.qty,
      COALESCE(summary.checked_at,direct_completion.wms_review_completed_at,completion.completed_at,
        CASE WHEN wms.fulfillment_mode IN ('system_complete','sub_warehouse_skip') THEN wms.end_time END) used_at
    FROM relevant_orders wms
    LEFT JOIN summary_times summary ON summary.order_id=btrim(wms.order_id)
    LEFT JOIN public.or_work_orders direct_completion ON direct_completion.id=wms.work_order_id
    LEFT JOIN LATERAL (
      SELECT w.wms_review_completed_at completed_at FROM public.or_work_orders w
      WHERE wms.work_order_id IS NULL AND summary.checked_at IS NULL
        AND btrim(w.work_order_name)=btrim(wms.order_id)
      ORDER BY w.created_at DESC LIMIT 1
    ) completion ON true
    WHERE wms.status='correct'
      AND NOT EXISTS (SELECT 1 FROM public.wms_requisitions r WHERE r.requisition_id=wms.order_id)
      AND upper(btrim(COALESCE(wms.order_id,''))) NOT LIKE 'REQ-%'
      AND (wms.work_order_id IS NOT NULL OR EXISTS (
        SELECT 1 FROM work_names o
        WHERE o.name=btrim(COALESCE(wms.order_id,''))
      ))
  ), usage_totals AS (
    SELECT product_code,sum(qty) qty FROM usage_rows
    WHERE used_at<=p_at GROUP BY product_code
  ), mapped_totals AS (
    SELECT g.sub_warehouse_id,COALESCE(sum(u.qty),0) qty
    FROM mappings g
    LEFT JOIN public.wh_sub_wms_map_sources s ON s.group_id=g.group_id
    LEFT JOIN public.pr_products p ON p.id=s.product_id
    LEFT JOIN usage_totals u ON u.product_code::text=p.product_code::text
    GROUP BY g.sub_warehouse_id
  ), balances AS (
    SELECT ids.sub_warehouse_id,COALESCE(l.qty,0)-
      CASE WHEN mapped.sub_warehouse_id IS NOT NULL THEN mapped.qty ELSE COALESCE(direct.qty,0) END qty
    FROM warehouse_ids ids
    LEFT JOIN ledger l ON l.sub_warehouse_id=ids.sub_warehouse_id
    LEFT JOIN mapped_totals mapped ON mapped.sub_warehouse_id=ids.sub_warehouse_id
    LEFT JOIN public.pr_products p ON p.id=p_product_id
    LEFT JOIN usage_totals direct ON direct.product_code::text=p.product_code::text
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'sub_warehouse_id',w.id,'name',w.name,'qty',b.qty
  ) ORDER BY w.name,w.id),'[]'::jsonb)
  FROM balances b JOIN public.wh_sub_warehouses w ON w.id=b.sub_warehouse_id
  WHERE w.created_at<=p_at AND (w.is_active OR b.qty<>0 OR EXISTS (
    SELECT 1 FROM ledger l WHERE l.sub_warehouse_id=w.id AND l.qty<>0
  ));
$$;
REVOKE ALL ON FUNCTION public.fn_audit_sub_warehouse_snapshot(uuid,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_audit_sub_warehouse_snapshot(uuid,timestamptz) TO authenticated;

-- Keep a permanent before/after record. Legacy NULL snapshots remain NULL and
-- are reconstructed through the existing RLS-protected RPC using the fixed formula.
CREATE TABLE public.inv_audit_sub_warehouse_corrections (
  item_id uuid PRIMARY KEY REFERENCES public.inv_audit_items(id) ON DELETE CASCADE,
  audit_id uuid NOT NULL REFERENCES public.inv_audits(id) ON DELETE CASCADE,
  cutoff_at timestamptz NOT NULL,
  previous_snapshot jsonb NOT NULL,
  corrected_snapshot jsonb NOT NULL,
  corrected_at timestamptz NOT NULL DEFAULT now(),
  reason text NOT NULL DEFAULT '673: subtract completed WMS work-order usage at audit cutoff'
);
ALTER TABLE public.inv_audit_sub_warehouse_corrections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inv_audit_sub_warehouse_corrections FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.inv_audit_sub_warehouse_corrections TO authenticated;
CREATE POLICY audit_sub_corrections_read ON public.inv_audit_sub_warehouse_corrections
FOR SELECT TO authenticated USING (
  EXISTS (SELECT 1 FROM public.inv_audit_items i WHERE i.id=item_id)
);

-- Serialize the one-time repair with Audit writes. No permanent trigger bypass.
LOCK TABLE public.inv_audits IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.inv_audit_items IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE audit_sub_repair_before ON COMMIT DROP AS
  SELECT id,to_jsonb(i)-'sub_warehouse_snapshot' data FROM public.inv_audit_items i;

INSERT INTO public.inv_audit_sub_warehouse_corrections(item_id,audit_id,cutoff_at,previous_snapshot,corrected_snapshot)
SELECT i.id,i.audit_id,COALESCE(a.frozen_at,a.created_at),i.sub_warehouse_snapshot,repair.snapshot
FROM public.inv_audit_items i JOIN public.inv_audits a ON a.id=i.audit_id
CROSS JOIN LATERAL (
  SELECT public.fn_audit_sub_warehouse_snapshot(i.product_id,COALESCE(a.frozen_at,a.created_at)) snapshot
) computed
CROSS JOIN LATERAL (
  -- Retain the original warehouse names, ordering, and scope of the frozen sheet.
  SELECT jsonb_agg(CASE WHEN corrected.value IS NULL THEN original.value
    ELSE jsonb_set(original.value,'{qty}',corrected.value->'qty') END ORDER BY original.n) snapshot
  FROM jsonb_array_elements(i.sub_warehouse_snapshot) WITH ORDINALITY original(value,n)
  LEFT JOIN LATERAL (
    SELECT candidate.value FROM jsonb_array_elements(computed.snapshot) candidate(value)
    WHERE candidate.value->>'sub_warehouse_id'=original.value->>'sub_warehouse_id'
  ) corrected ON true
) repair
WHERE i.sub_warehouse_snapshot IS NOT NULL AND repair.snapshot IS NOT NULL
  AND i.sub_warehouse_snapshot IS DISTINCT FROM repair.snapshot;

DO $$
DECLARE t record;
BEGIN
  -- Only these two known validation triggers need to be suspended. Fail closed
  -- if additional user triggers have been added that could change other fields.
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.inv_audit_items'::regclass
    AND NOT tgisinternal AND tgname NOT IN ('guard_audit_sub_warehouse_snapshot','guard_separate_audit_count')) THEN
    RAISE EXCEPTION 'Unexpected Audit item trigger; review before repairing snapshots';
  END IF;
  CREATE TEMP TABLE audit_sub_repair_triggers ON COMMIT DROP AS
    SELECT tgname,tgenabled FROM pg_trigger WHERE tgrelid='public.inv_audit_items'::regclass AND NOT tgisinternal;
  FOR t IN SELECT * FROM audit_sub_repair_triggers LOOP
    EXECUTE format('ALTER TABLE public.inv_audit_items DISABLE TRIGGER %I',t.tgname);
  END LOOP;
  UPDATE public.inv_audit_items i SET sub_warehouse_snapshot=c.corrected_snapshot
  FROM public.inv_audit_sub_warehouse_corrections c WHERE c.item_id=i.id;
  FOR t IN SELECT * FROM audit_sub_repair_triggers LOOP
    EXECUTE format('ALTER TABLE public.inv_audit_items %s TRIGGER %I',
      CASE t.tgenabled WHEN 'D' THEN 'DISABLE' WHEN 'R' THEN 'ENABLE REPLICA'
        WHEN 'A' THEN 'ENABLE ALWAYS' ELSE 'ENABLE' END,t.tgname);
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM public.inv_audit_items i FULL JOIN audit_sub_repair_before b USING(id)
    WHERE b.data IS DISTINCT FROM (to_jsonb(i)-'sub_warehouse_snapshot')
  ) THEN RAISE EXCEPTION 'Audit count data changed; rolling back snapshot repair'; END IF;
END;
$$;

NOTIFY pgrst,'reload schema';

-- Web import (607) is optional on some installations. Read its snapshot through
-- JSON so direct sales remain protected even when the column is absent.
-- ->> treats both a missing field and SQL NULL as NULL.
BEGIN;

CREATE OR REPLACE FUNCTION public.or_guard_sales_discount() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE state_ jsonb; role_ text; commercial_change boolean:=false;
BEGIN
 IF (TG_OP='INSERT' AND NEW.source_prebill_document_id IS NOT NULL) OR
  (TG_OP='UPDATE' AND NEW.source_prebill_document_id IS DISTINCT FROM OLD.source_prebill_document_id) THEN
  IF NEW.source_prebill_document_id IS NULL OR coalesce(current_setting('app.discount_prebill_conversion',true),'')<>NEW.source_prebill_document_id::text THEN
   RAISE EXCEPTION 'เอกสาร QT/PC ต้องเชื่อมผ่านขั้นตอนเปิดบิลเท่านั้น';
  END IF;
 END IF;
 IF TG_OP='INSERT' THEN NEW.automatic_discount_snapshot:=NULL; NEW.discount_approval_enabled:=true;
 ELSE
  NEW.automatic_discount_snapshot:=OLD.automatic_discount_snapshot;
  commercial_change:=public.or_discount_snapshot(to_jsonb(NEW),'[]')<>public.or_discount_snapshot(to_jsonb(OLD),'[]');
  NEW.discount_approval_enabled:=OLD.discount_approval_enabled OR NEW.discount_approval_enabled OR commercial_change;
 END IF;
 NEW.payment_not_required:=false;
 IF NEW.discount_approval_enabled AND NEW.source_marketplace_order_id IS NULL AND (to_jsonb(NEW)->>'web_import_snapshot') IS NULL AND upper(coalesce(NEW.bill_no,'')) NOT LIKE 'REQ%' THEN
  IF NEW.total_amount IS NULL OR NEW.price IS NULL OR NEW.discount IS NULL OR NEW.shipping_cost IS NULL THEN RAISE EXCEPTION 'กรุณาระบุยอดสินค้า ค่าส่ง ส่วนลด และยอดสุทธิ'; END IF;
  IF NEW.total_amount<0 OR NEW.discount<0 THEN RAISE EXCEPTION 'ยอดสุทธิและส่วนลดต้องไม่ติดลบ'; END IF;
  state_:=public.or_discount_state(NEW.id,to_jsonb(NEW),public.or_discount_items(NEW.id),
    coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.or_order_promotions p WHERE order_id=NEW.id),'[]'));
  NEW.payment_not_required:=coalesce((state_->>'zero_payment')::boolean,false);
  IF NEW.discount>0 AND NOT (state_->>'required')::boolean AND NEW.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ยกเลิก') THEN
   NEW.automatic_discount_snapshot:=public.or_discount_snapshot(to_jsonb(NEW),public.or_discount_items(NEW.id));
  END IF;

  IF NEW.payment_not_required AND NEW.status='ลงข้อมูลเสร็จสิ้น' THEN
   SELECT role INTO role_ FROM public.us_users WHERE NEW.admin_user IN(username,email) ORDER BY (username=NEW.admin_user) DESC NULLS LAST LIMIT 1;
   NEW.status:=CASE WHEN upper(NEW.channel_code)='WY' THEN 'ตรวจสอบแล้ว'
    WHEN role_='sales-tr' AND ((NEW.channel_code='PUMP' AND NEW.requires_confirm_design=false) OR (NEW.channel_code<>'PUMP' AND NOT coalesce(NEW.requires_confirm_design,false))) THEN 'รอตรวจคำสั่งซื้อ'
    WHEN NEW.channel_code='PUMP' AND NEW.requires_confirm_design=false THEN 'ไม่ต้องออกแบบ' ELSE 'ตรวจสอบแล้ว' END;
  END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.or_validate_sales_discount() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE o public.or_orders; id_ uuid; state_ jsonb;
BEGIN
 id_:=CASE WHEN TG_TABLE_NAME='or_orders' THEN (to_jsonb(NEW)->>'id')::uuid ELSE coalesce((to_jsonb(NEW)->>'order_id')::uuid,(to_jsonb(OLD)->>'order_id')::uuid) END;
 SELECT * INTO o FROM public.or_orders WHERE id=id_ FOR UPDATE;
 IF o.id IS NULL OR NOT o.discount_approval_enabled OR o.source_marketplace_order_id IS NOT NULL OR (to_jsonb(o)->>'web_import_snapshot') IS NOT NULL OR upper(coalesce(o.bill_no,'')) LIKE 'REQ%' THEN RETURN NULL; END IF;
 state_:=public.or_discount_state(o.id,to_jsonb(o),public.or_discount_items(o.id),coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.or_order_promotions p WHERE order_id=o.id),'[]'));
 UPDATE public.or_sales_discount_requests SET status=CASE WHEN o.status='ยกเลิก' THEN 'cancelled' ELSE 'stale' END
 WHERE order_id=o.id AND status IN ('pending','approved') AND (o.status='ยกเลิก' OR snapshot<>public.or_discount_snapshot(to_jsonb(o),public.or_discount_items(o.id)));
 IF o.status='ยกเลิก' THEN state_:=state_||jsonb_build_object('approved',false,'zero_payment',false); END IF;
 IF o.payment_not_required IS DISTINCT FROM coalesce((state_->>'zero_payment')::boolean,false) THEN
  UPDATE public.or_orders SET payment_not_required=coalesce((state_->>'zero_payment')::boolean,false) WHERE id=o.id;
 END IF;
 IF o.status NOT IN ('รอลงข้อมูล','ลงข้อมูลผิด','ตรวจสอบไม่ผ่าน','ตรวจสอบไม่สำเร็จ','ยกเลิก') THEN
  IF o.total_amount IS NULL OR o.price IS NULL OR o.shipping_cost IS NULL OR o.discount IS NULL OR o.total_amount<>round(o.price+o.shipping_cost-o.discount,2) OR o.total_amount<0 THEN RAISE EXCEPTION 'ยอดสุทธิไม่ตรงกับสินค้า ค่าส่ง และส่วนลด'; END IF;
  IF (state_->>'required')::boolean AND NOT (state_->>'approved')::boolean THEN RAISE EXCEPTION 'ส่วนลดต้องได้รับอนุมัติจาก superadmin และตรงกับรายการปัจจุบันก่อนยืนยันบิล'; END IF;
 END IF;
 RETURN NULL;
END $$;

COMMIT;

-- Production/packing start processing; Store confirms actual receipt and closes the job.
-- Admin/superadmin retain both permissions. Inventory and costing logic is unchanged.

CREATE OR REPLACE FUNCTION public.guard_pp_production_status_roles()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public AS $$
DECLARE v_role text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  SELECT role INTO v_role FROM public.us_users
  WHERE id = auth.uid() AND is_active IS TRUE;

  IF NEW.status = 'pending' AND (v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ส่งใบแปรรูปเพื่ออนุมัติ';
  ELSIF NEW.status IN ('approved', 'rejected') AND (v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์อนุมัติหรือปฏิเสธใบแปรรูป';
  ELSIF NEW.status = 'processing' AND (v_role IS NULL OR v_role NOT IN ('production', 'packing_staff', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์เริ่มแปรรูป';
  ELSIF NEW.status = 'completed' AND (v_role IS NULL OR v_role NOT IN ('store', 'admin', 'superadmin')) THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรับเข้าผลผลิต';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_complete_production_order_actual(p_order_id uuid, p_items jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := auth.uid(); v_role text; v_status text; v_item record; v_recipe uuid;
  v_input jsonb; v_m jsonb; v_b jsonb; v_r record; v_product record;
  v_actual numeric; v_used numeric; v_return numeric; v_waste numeric; v_short numeric;
  v_qty numeric; v_cost numeric; v_material_cost numeric; v_shortage_cost numeric;
  v_byproduct_cost numeric; v_total numeric; v_unit numeric; v_balance numeric;
  v_max numeric; v_move uuid; v_report jsonb; v_materials jsonb; v_byproducts jsonb;
  v_any_short boolean := false;
BEGIN
  SELECT role INTO v_role FROM us_users WHERE id = v_uid AND is_active IS TRUE;
  IF v_role IS NULL OR v_role NOT IN ('store','admin','superadmin') THEN
    RAISE EXCEPTION 'ไม่มีสิทธิ์ยืนยันรับเข้าผลผลิต';
  END IF;
  SELECT status INTO v_status FROM pp_production_orders WHERE id = p_order_id FOR UPDATE;
  IF v_status IS DISTINCT FROM 'processing' THEN RAISE EXCEPTION 'ใบแปรรูปไม่ได้อยู่ระหว่างการผลิต หรือปิดงานแล้ว'; END IF;
  -- Serialize edits to the item rows while validating and applying the receipt.
  PERFORM 1 FROM pp_production_order_items WHERE order_id = p_order_id ORDER BY id FOR UPDATE;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'กรุณาระบุผลผลิตจริง'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items)) <> (SELECT count(*) FROM pp_production_order_items WHERE order_id = p_order_id)
     OR (SELECT count(DISTINCT x->>'item_id') FROM jsonb_array_elements(p_items) x) <> jsonb_array_length(p_items)
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) x WHERE NOT EXISTS
       (SELECT 1 FROM pp_production_order_items oi WHERE oi.order_id = p_order_id AND oi.id::text = x->>'item_id')) THEN
    RAISE EXCEPTION 'รายการผลผลิตไม่ตรงกับใบแปรรูป';
  END IF;

  -- Lock recipes and their lines for a consistent completion snapshot.
  PERFORM 1 FROM pp_recipes WHERE product_id IN (SELECT product_id FROM pp_production_order_items WHERE order_id = p_order_id) ORDER BY id FOR SHARE;
  PERFORM 1 FROM pp_recipe_includes WHERE recipe_id IN (SELECT r.id FROM pp_recipes r JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id) ORDER BY id FOR SHARE;
  PERFORM 1 FROM pp_recipe_removes WHERE recipe_id IN (SELECT r.id FROM pp_recipes r JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id) ORDER BY id FOR SHARE;
  -- Create and lock balance rows in a stable order, including shared materials.
  FOR v_product IN
    SELECT product_id FROM pp_production_order_items WHERE order_id=p_order_id
    UNION SELECT i.product_id FROM pp_recipe_includes i JOIN pp_recipes r ON r.id=i.recipe_id JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id
    UNION SELECT i.product_id FROM pp_recipe_removes i JOIN pp_recipes r ON r.id=i.recipe_id JOIN pp_production_order_items oi ON oi.product_id=r.product_id WHERE oi.order_id=p_order_id
    ORDER BY product_id
  LOOP
    INSERT INTO inv_stock_balances(product_id,on_hand,reserved,safety_stock) VALUES(v_product.product_id,0,0,0) ON CONFLICT(product_id) DO NOTHING;
    PERFORM 1 FROM inv_stock_balances WHERE product_id=v_product.product_id FOR UPDATE;
  END LOOP;

  FOR v_item IN SELECT oi.*,p.product_code,p.product_name FROM pp_production_order_items oi JOIN pr_products p ON p.id=oi.product_id WHERE order_id=p_order_id ORDER BY oi.id LOOP
    SELECT x INTO v_input FROM jsonb_array_elements(p_items) x WHERE x->>'item_id'=v_item.id::text;
    IF COALESCE(v_input->>'actual_qty','') !~ '^\d+(\.\d{1,2})?$' THEN RAISE EXCEPTION 'จำนวนผลิตจริงไม่ถูกต้อง'; END IF;
    v_actual := (v_input->>'actual_qty')::numeric;
    IF v_actual > v_item.qty THEN RAISE EXCEPTION 'จำนวนผลิตจริงเกินจำนวนที่ขอ'; END IF;
    IF v_actual < v_item.qty THEN
      v_any_short := true;
      IF COALESCE(v_input->>'reason_code','') NOT IN ('วัตถุดิบในห่อไม่ครบ','วัตถุดิบไม่เพียงพอ','ชำรุดระหว่างผลิต','สูญเสียระหว่างผลิต','อื่น ๆ') OR btrim(COALESCE(v_input->>'reason',''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลและรายละเอียดที่ผลิตขาด'; END IF;
    END IF;
    SELECT id,max_stock INTO v_recipe,v_max FROM pp_recipes WHERE product_id=v_item.product_id;
    IF v_recipe IS NULL THEN RAISE EXCEPTION 'ไม่พบสูตรแปรรูป'; END IF;
    IF jsonb_typeof(v_input->'materials') IS DISTINCT FROM 'array' OR jsonb_typeof(v_input->'byproducts') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'กรุณาระบุรายการวัตถุดิบและสินค้าที่แยกคืน'; END IF;
    IF jsonb_array_length(v_input->'materials') <> (SELECT count(DISTINCT product_id) FROM pp_recipe_includes WHERE recipe_id=v_recipe)
       OR (SELECT count(DISTINCT x->>'product_id') FROM jsonb_array_elements(v_input->'materials') x) <> jsonb_array_length(v_input->'materials')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_input->'materials') x WHERE NOT EXISTS (SELECT 1 FROM pp_recipe_includes WHERE recipe_id=v_recipe AND product_id::text=x->>'product_id')) THEN RAISE EXCEPTION 'รายการวัตถุดิบไม่ตรงกับสูตร กรุณาเปิดบันทึกผลผลิตใหม่'; END IF;
    IF jsonb_array_length(v_input->'byproducts') <> (SELECT count(DISTINCT product_id) FROM pp_recipe_removes WHERE recipe_id=v_recipe)
       OR (SELECT count(DISTINCT x->>'product_id') FROM jsonb_array_elements(v_input->'byproducts') x) <> jsonb_array_length(v_input->'byproducts')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_input->'byproducts') x WHERE NOT EXISTS (SELECT 1 FROM pp_recipe_removes WHERE recipe_id=v_recipe AND product_id::text=x->>'product_id')) THEN RAISE EXCEPTION 'รายการสินค้าที่แยกคืนไม่ตรงกับสูตร'; END IF;
    v_material_cost:=0; v_shortage_cost:=0; v_byproduct_cost:=0; v_materials:='[]'; v_byproducts:='[]';
    FOR v_r IN SELECT i.product_id,round(sum(i.qty)*v_item.qty,2) planned_qty,p.product_code,p.product_name FROM pp_recipe_includes i JOIN pr_products p ON p.id=i.product_id WHERE recipe_id=v_recipe GROUP BY i.product_id,p.product_code,p.product_name ORDER BY i.product_id LOOP
      SELECT x INTO v_m FROM jsonb_array_elements(v_input->'materials') x WHERE x->>'product_id'=v_r.product_id::text;
      IF EXISTS (SELECT 1 FROM unnest(ARRAY['used_qty','returned_qty','waste_qty','shortage_qty']) k WHERE COALESCE(v_m->>k,'') !~ '^\d+(\.\d{1,2})?$') THEN RAISE EXCEPTION 'จำนวนวัตถุดิบไม่ถูกต้อง'; END IF;
      v_used:=(v_m->>'used_qty')::numeric; v_return:=(v_m->>'returned_qty')::numeric; v_waste:=(v_m->>'waste_qty')::numeric; v_short:=(v_m->>'shortage_qty')::numeric;
      IF v_used+v_return+v_waste+v_short <> v_r.planned_qty THEN RAISE EXCEPTION 'ยอดใช้ คืน สูญเสีย และขาดจากห่อ ของ % ไม่ตรงกับยอดตามเอกสาร %',v_r.product_code,v_r.planned_qty; END IF;
      IF (v_used<>v_r.planned_qty OR v_waste>0 OR v_short>0) AND btrim(COALESCE(v_m->>'reason',''))='' THEN RAISE EXCEPTION 'กรุณาระบุเหตุผลส่วนต่างวัตถุดิบ %',v_r.product_code; END IF;
      v_qty:=v_used+v_waste+v_short;
      SELECT on_hand INTO v_balance FROM inv_stock_balances WHERE product_id=v_r.product_id;
      IF v_balance < v_qty THEN RAISE EXCEPTION 'สต็อกวัตถุดิบ % ไม่เพียงพอ ต้องการ % คงเหลือ %',v_r.product_code,v_qty,v_balance; END IF;
      -- Nothing was deducted at start: unused returns remain in stock, no extra receipt.
      v_cost:=0;
      IF v_used+v_waste>0 THEN
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by) VALUES(v_r.product_id,'pp_consume',-(v_used+v_waste),'pp_production_orders',p_order_id,'ใช้ผลิตจริงและสูญเสีย: '||COALESCE(v_m->>'reason',''),v_uid) RETURNING id INTO v_move;
        v_cost:=fn_consume_stock_fifo(v_r.product_id,v_used+v_waste,v_move);
        v_material_cost:=v_material_cost+v_cost;
      END IF;
      v_m:=jsonb_build_object('product_id',v_r.product_id,'product_code',v_r.product_code,'product_name',v_r.product_name,'planned_qty',v_r.planned_qty,'used_qty',v_used,'returned_qty',v_return,'waste_qty',v_waste,'shortage_qty',v_short,'reason',COALESCE(v_m->>'reason',''),'material_cost',v_cost);
      v_cost:=0;
      IF v_short>0 THEN
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by) VALUES(v_r.product_id,'pp_shortage',-v_short,'pp_production_orders',p_order_id,'ขาดจากห่อ: '||(v_m->>'reason'),v_uid) RETURNING id INTO v_move;
        v_cost:=fn_consume_stock_fifo(v_r.product_id,v_short,v_move);
        v_shortage_cost:=v_shortage_cost+v_cost;
      END IF;
      UPDATE inv_stock_balances SET on_hand=on_hand-v_qty,updated_at=now() WHERE product_id=v_r.product_id;
      PERFORM fn_recalc_product_landed_cost(v_r.product_id);
      v_materials:=v_materials||jsonb_build_array(v_m||jsonb_build_object('shortage_cost',v_cost));
    END LOOP;
    FOR v_r IN SELECT i.product_id,round(sum(i.qty)*v_item.qty,2) planned_qty,sum(i.qty*i.unit_cost)/NULLIF(sum(i.qty),0) unit_cost,p.product_code,p.product_name FROM pp_recipe_removes i JOIN pr_products p ON p.id=i.product_id WHERE recipe_id=v_recipe GROUP BY i.product_id,p.product_code,p.product_name ORDER BY i.product_id LOOP
      SELECT x INTO v_b FROM jsonb_array_elements(v_input->'byproducts') x WHERE x->>'product_id'=v_r.product_id::text;
      IF COALESCE(v_b->>'qty','') !~ '^\d+(\.\d{1,2})?$' THEN RAISE EXCEPTION 'จำนวนสินค้าที่แยกคืนไม่ถูกต้อง'; END IF;
      v_qty:=(v_b->>'qty')::numeric; v_cost:=v_qty*COALESCE(v_r.unit_cost,0);
      IF v_r.unit_cost<0 THEN RAISE EXCEPTION 'ต้นทุนสินค้าแยกคืนต้องไม่ติดลบ'; END IF;
      v_byproduct_cost:=v_byproduct_cost+v_cost;
      IF v_qty>0 THEN
        UPDATE inv_stock_balances SET on_hand=on_hand+v_qty,updated_at=now() WHERE product_id=v_r.product_id;
        INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by,unit_cost,total_cost) VALUES(v_r.product_id,'pp_remove',v_qty,'pp_production_orders',p_order_id,'รับสินค้าแยกคืนตามจริง',v_uid,v_r.unit_cost,v_cost);
        INSERT INTO inv_stock_lots(product_id,qty_initial,qty_remaining,unit_cost,ref_type,ref_id) VALUES(v_r.product_id,v_qty,v_qty,v_r.unit_cost,'pp_production_orders',p_order_id);
        PERFORM fn_recalc_product_landed_cost(v_r.product_id);
      END IF;
      v_byproducts:=v_byproducts||jsonb_build_array(jsonb_build_object('product_id',v_r.product_id,'product_code',v_r.product_code,'product_name',v_r.product_name,'planned_qty',v_r.planned_qty,'qty',v_qty,'unit_cost',v_r.unit_cost,'total_cost',v_cost));
    END LOOP;
    v_total:=v_material_cost-v_byproduct_cost;
    IF v_total<0 THEN RAISE EXCEPTION 'มูลค่าสินค้าแยกคืนเกินต้นทุนวัตถุดิบที่ใช้จริง'; END IF;
    v_unit:=CASE WHEN v_actual>0 THEN round(v_total/v_actual,4) ELSE 0 END;
    SELECT on_hand INTO v_balance FROM inv_stock_balances WHERE product_id=v_item.product_id;
    IF v_actual>0 AND v_max IS NOT NULL AND v_balance+v_actual>v_max THEN RAISE EXCEPTION 'จำนวนรับเข้าจริงเกิน Max ที่กำหนด'; END IF;
    IF v_actual>0 THEN
      UPDATE inv_stock_balances SET on_hand=on_hand+v_actual,updated_at=now() WHERE product_id=v_item.product_id;
      INSERT INTO inv_stock_movements(product_id,movement_type,qty,ref_type,ref_id,note,created_by,unit_cost,total_cost) VALUES(v_item.product_id,'pp_produce',v_actual,'pp_production_orders',p_order_id,'รับผลผลิตจริง ปิดงานไม่ค้างยอดขาด',v_uid,v_unit,v_total);
      INSERT INTO inv_stock_lots(product_id,qty_initial,qty_remaining,unit_cost,ref_type,ref_id) VALUES(v_item.product_id,v_actual,v_actual,v_unit,'pp_production_orders',p_order_id);
      PERFORM fn_recalc_product_landed_cost(v_item.product_id);
    END IF;
    v_report:=jsonb_build_object('item_id',v_item.id,'product_code',v_item.product_code,'product_name',v_item.product_name,'planned_qty',v_item.qty,'actual_qty',v_actual,'reason_code',COALESCE(v_input->>'reason_code',''),'reason',COALESCE(v_input->>'reason',''),'materials',v_materials,'byproducts',v_byproducts,'material_cost',v_material_cost,'shortage_cost',v_shortage_cost,'byproduct_cost',v_byproduct_cost,'production_loss_cost',CASE WHEN v_actual=0 THEN v_total ELSE 0 END,'unit_cost',v_unit,'total_cost',CASE WHEN v_actual>0 THEN v_total ELSE 0 END);
    UPDATE pp_production_order_items SET actual_qty=v_actual,completion_report=v_report,unit_cost=v_unit,total_cost=CASE WHEN v_actual>0 THEN v_total ELSE 0 END WHERE id=v_item.id;
  END LOOP;
  UPDATE pp_production_orders SET status='completed',completion_short=v_any_short,completed_by=v_uid,completed_at=now() WHERE id=p_order_id;
END;
$$;

